/* Workday Functional Test Agent — styles */

:root {

  /* Automation Anywhere orange enterprise palette */

  --aa-orange: #ff6a3d;

  --aa-orange-dark: #e2552b;

  --aa-orange-soft: #fff3ec;

  --aa-coral: #ff8a4c;



  --bg: #f6f7f9;

  --surface: #ffffff;

  --surface-2: #fafbfc;

  --border: #e5e8ef;

  --border-strong: #d0d5e0;



  --text: #1a1d26;

  --text-2: #3a4255;

  --text-3: #5c6578;

  --text-4: #7a8499;



  --mist-200: #1a1d26;

  --mist-300: #3a4255;

  --mist-400: #5c6578;

  --mist-500: #7a8499;

  --ink-600: #d0d5e0;

  --ink-700: #e5e8ef;

  --ink-800: #eef0f6;

  --ink-850: #f7f8fb;

  --ink-900: #ffffff;

  --ink-950: #f6f7f9;



  --blue: var(--aa-orange);

  --sky: var(--aa-orange-dark);

  --violet: var(--aa-orange);

  --magenta: var(--aa-coral);

  --aa-purple: var(--aa-orange);

  --aa-purple-dark: var(--aa-orange-dark);

  --aa-purple-soft: var(--aa-orange-soft);

  --pass: var(--aa-orange);

  --pass-dark: var(--aa-orange-dark);

  --pass-mid: #ff8a4c;

  --pass-light: #ffb087;

  --fail: #9f1239;

  --warn: #c47a00;

  --info: #f5a623;

  --info-soft: #fff6e5;

  --run: #f5a623;

  --run-soft: #fff6e5;



  --font: "Segoe UI", system-ui, -apple-system, sans-serif;

  --mono: "Segoe UI", system-ui, sans-serif;

  --shadow: 0 1px 2px rgba(26, 29, 38, 0.04), 0 8px 24px rgba(26, 29, 38, 0.05);

}



*,

*::before,

*::after {

  box-sizing: border-box;

}



html,

body {

  margin: 0;

  height: 100%;

  min-height: 100%;

  background: var(--bg);

  color: var(--text);

  font-family: var(--font);

  font-size: 15px;

  line-height: 1.5;

}



/* Hide scrollbars, keep scrolling */

* {

  scrollbar-width: none;

  -ms-overflow-style: none;

}

*::-webkit-scrollbar {

  width: 0 !important;

  height: 0 !important;

  display: none !important;

}



a {

  color: inherit;

  text-decoration: none;

}



button,

input,

select {

  font: inherit;

}



button {

  cursor: pointer;

  border: 0;

  background: none;

  color: inherit;

}



table {

  width: 100%;

  border-collapse: collapse;

  table-layout: auto;

}



.app {

  display: flex;

  min-height: 100%;

  height: 100%;

}



.sidebar {

  position: sticky;

  top: 0;

  width: 248px;

  height: 100%;

  flex-shrink: 0;

  border-right: 1px solid var(--border);

  background: var(--surface);

  display: none;

  flex-direction: column;

}



@media (min-width: 960px) {

  .sidebar {

    display: flex;

  }

}



.brand {

  display: flex;

  align-items: center;

  gap: 14px;

  padding: 22px 18px 18px;

  border-bottom: 1px solid var(--border);

  margin-bottom: 8px;

}



.brand-mark {

  width: 46px;

  height: 46px;

  border-radius: 12px;

  background: linear-gradient(145deg, #ff7a4d 0%, #ff6a3d 45%, #e2552b 100%);

  display: grid;

  place-items: center;

  color: #fff;

  font-weight: 800;

  font-size: 14px;

  letter-spacing: -0.02em;

  box-shadow: 0 10px 22px rgba(255, 106, 61, 0.35);

  flex-shrink: 0;

}



.brand-copy {

  min-width: 0;

}



.brand strong {

  display: block;

  color: var(--text);

  font-size: 13px;

  font-weight: 800;

  line-height: 1.1;

  letter-spacing: -0.025em;

}



.brand span {

  display: block;

  color: var(--aa-orange-dark);

  font-size: 16px;

  font-weight: 750;

  line-height: 1.1;

  letter-spacing: -0.025em;

  margin-top: 0;

}



.nav {

  padding: 8px 12px;

  display: flex;

  flex-direction: column;

  gap: 4px;

}



.nav a {

  display: flex;

  align-items: center;

  gap: 10px;

  padding: 12px 14px;

  border-radius: 10px;

  color: var(--text-3);

  font-size: 15px;

  font-weight: 550;

  transition: 0.15s ease;

  position: relative;

  white-space: nowrap;

}



.nav-icon {

  width: 18px;

  height: 18px;

  flex-shrink: 0;

  opacity: 0.85;

}



.nav a:hover .nav-icon,

.nav a.active .nav-icon {

  opacity: 1;

}



.nav a:hover {

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

}



.nav a.active {

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

  font-weight: 650;

}



.nav a.active::before {

  content: "";

  position: absolute;

  left: 0;

  top: 50%;

  transform: translateY(-50%);

  width: 3px;

  height: 20px;

  border-radius: 0 4px 4px 0;

  background: var(--aa-orange);

}



.main-wrap {

  flex: 1;

  min-width: 0;

  display: flex;

  flex-direction: column;

}



.topbar {

  position: sticky;

  top: 0;

  z-index: 20;

  min-height: 60px;

  display: flex;

  align-items: center;

  gap: 12px;

  padding: 10px 12px;

  border-bottom: 1px solid var(--border);

  background: #ffffff;

  flex-wrap: wrap;

}



.topbar h1 {

  margin: 0;

  flex: 1;

  min-width: 120px;

  font-size: 18px;

  font-weight: 650;

  color: var(--text);

  white-space: nowrap;

}



.online {

  display: inline-flex;

  align-items: center;

  gap: 8px;

  padding: 6px 12px;

  border-radius: 999px;

  border: 1px solid #ffd2bf;

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

  font-size: 13px;

  font-weight: 600;

  white-space: nowrap;

}



.dot {

  width: 8px;

  height: 8px;

  border-radius: 50%;

  background: currentColor;

  animation: pulse 1.4s ease-in-out infinite;

  flex-shrink: 0;

}



@keyframes pulse {

  0%,

  100% {

    opacity: 1;

  }

  50% {

    opacity: 0.35;

  }

}



.user-menu {

  position: relative;

}



.user-chip {

  display: inline-flex;

  align-items: center;

  gap: 10px;

  padding: 5px 12px 5px 5px;

  border-radius: 999px;

  border: 1px solid var(--border);

  background: var(--surface);

  font-size: 14px;

  color: var(--text-2);

  font-weight: 550;

  white-space: nowrap;

  cursor: pointer;

}



.user-chip:hover,

.user-menu:hover .user-chip {

  border-color: #ffd2bf;

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

}



.user-dropdown {

  position: absolute;

  top: calc(100% + 8px);

  right: 0;

  min-width: 168px;

  padding: 8px;

  border-radius: 12px;

  border: 1px solid var(--border);

  background: #fff;

  box-shadow:
    0 4px 6px -2px rgba(26, 29, 38, 0.06),
    0 16px 32px -12px rgba(26, 29, 38, 0.22);

  opacity: 0;

  visibility: hidden;

  transform: translateY(-6px);

  transition: opacity 0.18s ease, transform 0.18s ease, visibility 0.18s ease;

  z-index: 40;

}



.user-menu:hover .user-dropdown,

.user-menu:focus-within .user-dropdown {

  opacity: 1;

  visibility: visible;

  transform: translateY(0);

}



.user-dropdown button {

  width: 100%;

  display: flex;

  align-items: center;

  gap: 8px;

  text-align: left;

  padding: 10px 12px;

  border-radius: 8px;

  border: 0;

  background: rgba(159, 18, 57, 0.08);

  color: #9f1239;

  font-size: 14px;

  font-weight: 600;

  cursor: pointer;

}



.user-dropdown .nav-icon {

  width: 16px;

  height: 16px;

  opacity: 0.9;

}



.user-dropdown button:hover {

  background: rgba(159, 18, 57, 0.14);

  color: #9f1239;

}



.user-chip .brand-mark {

  width: 30px;

  height: 30px;

  font-size: 11px;

  border-radius: 50%;

  box-shadow: none;

  align-self: center;

}



.content {

  padding: 12px 10px;

  animation: rise 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;

  min-width: 0;

  max-width: 100%;

  width: 100%;

  box-sizing: border-box;

}



@keyframes rise {

  from {

    opacity: 0;

    transform: translateY(8px);

  }

  to {

    opacity: 1;

    transform: translateY(0);

  }

}



.panel {

  background: var(--surface);

  border: 1px solid var(--border);

  border-radius: 14px;

  box-shadow: var(--shadow);

  min-width: 0;

  max-width: 100%;

  box-sizing: border-box;

}



.panel-hd {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

  padding: 16px 20px;

  border-bottom: 1px solid var(--border);

  flex-wrap: wrap;

}



.panel-hd h2 {

  margin: 0;

  font-size: 16px;

  font-weight: 650;

  color: var(--text);

}



.panel-bd {

  padding: 20px;

}



.stack {

  display: flex;

  flex-direction: column;

  gap: 20px;

  min-width: 0;

  max-width: 100%;

  width: 100%;

  box-sizing: border-box;

}



.grid-2,

.grid-3,

.grid-4 {

  display: grid;

  gap: 16px;

  width: 100%;

  max-width: 100%;

  min-width: 0;

}



.grid-2 > *,

.grid-3 > *,

.grid-4 > * {

  min-width: 0;

  max-width: 100%;

}



.grid-2 {

  grid-template-columns: minmax(0, 1fr);

}

.grid-3 {

  grid-template-columns: minmax(0, 1fr);

}

.grid-4 {

  grid-template-columns: repeat(2, minmax(0, 1fr));

}



@media (min-width: 720px) {

  .grid-2 {

    grid-template-columns: repeat(2, minmax(0, 1fr));

  }

  .grid-3 {

    grid-template-columns: repeat(3, minmax(0, 1fr));

  }

}



@media (min-width: 900px) {

  .grid-4 {

    grid-template-columns: repeat(4, minmax(0, 1fr));

  }

  .xl-2-1 {

    grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);

  }

  .xl-1-2 {

    grid-template-columns: minmax(0, 1fr) minmax(0, 2fr);

  }

}



.page-hd {

  display: flex;

  flex-wrap: wrap;

  align-items: center;

  justify-content: space-between;

  gap: 14px;

}



.page-hd h2 {

  margin: 0;

  font-size: 24px;

  font-weight: 700;

  color: var(--text);

  letter-spacing: -0.02em;

}



.page-hd p {

  margin: 8px 0 0;

  color: var(--text-3);

  font-size: 15px;

}



.page-hd .btn {

  flex-shrink: 0;

  white-space: nowrap;

}



.stat {

  position: relative;

  overflow: hidden;

  padding: 18px 20px;

}



.stat::before {

  content: "";

  position: absolute;

  left: 0;

  top: 0;

  bottom: 0;

  width: 4px;

  background: linear-gradient(180deg, var(--aa-orange), var(--aa-coral));

}



.stat .label {

  margin: 0;

  font-size: 12px;

  text-transform: uppercase;

  letter-spacing: 0.08em;

  color: var(--text-4);

  font-weight: 650;

}



.stat .value {

  margin: 10px 0 0;

  font-size: 32px;

  font-weight: 700;

  color: var(--text);

  font-variant-numeric: tabular-nums;

}



.stat .hint {

  margin: 8px 0 0;

  font-size: 13px;

  color: var(--text-4);

}



.badge {

  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding: 5px 10px;

  border-radius: 999px;

  font-size: 12px;

  font-weight: 650;

  text-transform: uppercase;

  letter-spacing: 0.03em;

  border: 1px solid transparent;

  white-space: nowrap;

}



.badge.pass {

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

  border-color: #ffd2bf;

}

.badge.fail {

  background: rgba(159, 18, 57, 0.1);

  color: #9f1239;

  border-color: rgba(159, 18, 57, 0.28);

}

.badge.warn {

  background: #fff8e8;

  color: var(--warn);

  border-color: #f3dfae;

}

.badge.info {

  background: var(--info-soft);

  color: #9a6b0a;

  border-color: #f5d48a;

}

.badge.violet {

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

  border-color: #ffd2bf;

}

.badge.neutral {

  background: #f1f3f8;

  color: var(--text-3);

  border-color: var(--border);

}



.btn {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 8px;

  height: 44px;

  padding: 0 18px;

  border-radius: 10px;

  font-size: 15px;

  font-weight: 650;

  transition: 0.15s ease;

  white-space: nowrap;

  flex-shrink: 0;

}



.btn-primary {

  background: linear-gradient(135deg, var(--aa-orange), var(--aa-coral));

  color: #fff;

  box-shadow: 0 10px 22px -10px rgba(255, 106, 61, 0.75);

}



.btn-success {

  background: linear-gradient(145deg, #0f172a 0%, #334155 52%, #64748b 100%);

  color: #fff;

  box-shadow: 0 10px 22px -10px rgba(15, 23, 42, 0.65);

}



.btn-success:hover {

  filter: brightness(1.06);

}



.btn-outline {

  border: 1px solid var(--border-strong);

  background: var(--surface);

  color: var(--text-2);

}



.btn-outline:hover {

  border-color: var(--aa-orange);

  color: var(--aa-orange-dark);

  background: var(--aa-orange-soft);

}



.btn-danger {

  border: 1px solid #f7c9d0;

  background: #fff0f2;

  color: var(--fail);

}



.btn:disabled {

  opacity: 0.45;

  cursor: not-allowed;

}



.btn-row {

  display: flex;

  flex-wrap: wrap;

  gap: 10px;

  align-items: center;

}



.field {

  display: flex;

  flex-direction: column;

  gap: 8px;

  min-width: 0;

}



.field label {

  font-size: 12px;

  font-weight: 650;

  text-transform: uppercase;

  letter-spacing: 0.06em;

  color: var(--text-4);

}



.field input,

.field select {

  height: 44px;

  width: 100%;

  padding: 0 14px;

  border-radius: 10px;

  border: 1px solid var(--border-strong);

  color: var(--text);

  outline: none;

  transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;

}



.field input {

  background: var(--surface);

}



.field select {

  padding-right: 42px;

  cursor: pointer;

  background-color: var(--surface);

}



.field input:hover,

.field select:hover {

  border-color: #b8bfd0;

}



.field input:hover {

  background: var(--surface-2);

}



.field select:hover {

  background-color: var(--surface-2);

}



.field input:focus,

.field select:focus {

  border-color: var(--aa-orange);

  box-shadow: 0 0 0 3px rgba(255, 106, 61, 0.15);

}



.field input:focus {

  background: var(--surface);

}



.field select:focus {

  background-color: var(--surface);

}



.progress {

  height: 8px;

  width: 100%;

  border-radius: 999px;

  background: #e9ecf4;

  overflow: hidden;

}



.progress > span {

  display: block;

  height: 100%;

  border-radius: 999px;

  background: linear-gradient(90deg, #ff6a3d, #ff8a4c);

  transition: width 0.4s ease;

}



.progress.green > span {

  background: linear-gradient(90deg, #ff6a3d, #ff8a4c);

}

.progress.amber > span {

  background: linear-gradient(90deg, #ff6a3d, #ff8a4c);

}

.progress.red > span {

  background: #9f1239;

}

.progress.blue > span,

.progress.info > span {

  background: linear-gradient(90deg, #ffc857, #f5a623);

}



th {

  position: sticky;

  top: 0;

  z-index: 1;

  padding: 14px 16px;

  text-align: left;

  font-size: 12px;

  font-weight: 650;

  text-transform: uppercase;

  letter-spacing: 0.06em;

  color: var(--text-4);

  background: #fafafc;

  border-bottom: 1px solid var(--border);

  white-space: nowrap;

}



td {

  padding: 14px 16px;

  font-size: 14.5px;

  color: var(--text-2);

  border-top: 1px solid var(--border);

  vertical-align: middle;

}



tr:hover td {

  background: #fff8f4;

}



.mono {

  font-family: var(--mono);

  font-variant-numeric: tabular-nums;

}



.muted {

  color: var(--text-4);

}



.right {

  text-align: right;

}



.scroll {

  max-height: 62vh;

  overflow: auto;

  width: 100%;

  max-width: 100%;

  -webkit-overflow-scrolling: touch;

}



.scroll table {

  width: 100%;

  min-width: 760px;

}



.scroll td {

  word-break: break-word;

}



.empty {

  padding: 56px 20px;

  text-align: center;

  color: var(--text-4);

  font-size: 15px;

}



.bar-chart {

  display: flex;

  align-items: flex-end;

  gap: 10px;

  height: 200px;

  padding: 12px 4px 0;

}



.bar-col {

  flex: 1;

  display: flex;

  flex-direction: column;

  justify-content: flex-end;

  align-items: center;

  gap: 8px;

  min-width: 0;

}



.bar-stack {

  width: 100%;

  max-width: 34px;

  display: flex;

  flex-direction: column-reverse;

  border-radius: 7px 7px 0 0;

  overflow: hidden;

  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35);

}



.bar-seg {

  width: 100%;

  position: relative;

}



.bar-seg-pass {

  background: linear-gradient(

    180deg,

    #ffb087 0%,

    #ff8a4c 28%,

    #ff6a3d 62%,

    #e2552b 100%

  );

}



.bar-seg-fail {

  background: linear-gradient(180deg, #e11d48 0%, #9f1239 55%, #7f1d1d 100%);

}



.bar-seg-wait {

  background: linear-gradient(180deg, #ffd98a 0%, #f5a623 55%, #d4890f 100%);

}



.bar-seg-pass::after {

  content: "";

  position: absolute;

  inset: 0;

  background: linear-gradient(

    90deg,

    rgba(255, 255, 255, 0.28) 0%,

    rgba(255, 255, 255, 0.05) 42%,

    rgba(226, 85, 43, 0.12) 100%

  );

  pointer-events: none;

}



.bar-seg-wait::after {

  content: "";

  position: absolute;

  inset: 0;

  background: linear-gradient(

    90deg,

    rgba(255, 255, 255, 0.35) 0%,

    rgba(255, 255, 255, 0.08) 45%,

    rgba(154, 107, 10, 0.12) 100%

  );

  pointer-events: none;

}



.bar-label {

  font-size: 12px;

  color: var(--text-4);

  font-weight: 600;

}



.region-row {

  margin-bottom: 16px;

}

.region-row:last-child {

  margin-bottom: 0;

}



.region-meta {

  display: flex;

  justify-content: space-between;

  margin-bottom: 8px;

  font-size: 14px;

  color: var(--text-2);

  font-weight: 550;

  gap: 8px;

  min-width: 0;

}



.region-meta span {

  min-width: 0;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;

}



.issue {

  display: flex;

  gap: 12px;

  align-items: flex-start;

  min-width: 0;

  max-width: 100%;

  box-sizing: border-box;

  padding: 16px 20px;

  border-top: 1px solid var(--border);

}



.issue p {

  margin: 0;

  flex: 1;

  min-width: 0;

  font-size: 14px;

  color: var(--text-3);

  display: -webkit-box;

  -webkit-line-clamp: 2;

  -webkit-box-orient: vertical;

  overflow: hidden;

  word-break: break-word;

}



.issue .badge,

.issue strong {

  flex-shrink: 0;

}



.filters {

  display: grid;

  gap: 14px;

  grid-template-columns: minmax(0, 1fr);

  padding: 20px;

  align-items: end;

}



@media (min-width: 640px) {

  .filters {

    grid-template-columns: repeat(2, minmax(0, 1fr));

  }

}



@media (min-width: 1100px) {

  .filters {

    grid-template-columns: minmax(0, 1.6fr) repeat(3, minmax(0, 1fr));

  }

}



/* Keep action buttons on one row; full-width row when filters are 2-col */

.filters .field-actions {

  min-width: 0;

}



@media (max-width: 1099px) {

  .filters .field-actions {

    grid-column: 1 / -1;

  }

}



.filters .btn-row {

  height: auto;

  min-height: 44px;

  flex-wrap: nowrap;

  width: 100%;

}



.filters .btn-row .btn {

  white-space: nowrap;

  flex-shrink: 0;

}



.filters .field-actions .btn-row {

  justify-content: flex-start;

}



.catalog-actions {
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
}

.catalog-actions .btn,
.catalog-actions .catalog-chip {
  height: 36px;
  min-height: 36px;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 14px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 650;
  white-space: nowrap;
  flex-shrink: 0;
  line-height: 1;
}

.catalog-actions .btn {
  white-space: nowrap;
  flex-shrink: 0;
}

.catalog-chip {
  border: 1px solid var(--border-strong);
  background: var(--surface-2);
  color: var(--text-3);
}

.catalog-chip-accent {
  border-color: #ffd2bf;
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
}



.overview-side,

.overview-split {

  min-width: 0;

  max-width: 100%;

}



.overview-side .panel {

  overflow: hidden;

}



.mobile-nav {

  display: flex;

  gap: 8px;

  overflow-x: auto;

  padding: 0 0 16px;

  -webkit-overflow-scrolling: touch;

}



@media (min-width: 960px) {

  .mobile-nav {

    display: none;

  }

}



.mobile-nav a {

  display: inline-flex;

  align-items: center;

  gap: 8px;

  white-space: nowrap;

  padding: 8px 14px;

  border-radius: 999px;

  border: 1px solid var(--border);

  color: var(--text-3);

  font-size: 14px;

  background: var(--surface);

  flex-shrink: 0;

}



.mobile-nav .nav-icon {

  width: 15px;

  height: 15px;

}



.mobile-nav a.active {

  border-color: #ffd2bf;

  color: var(--aa-orange-dark);

  background: var(--aa-orange-soft);

  font-weight: 650;

}



.log {

  font-size: 13px;

  max-height: 280px;

  overflow: auto;

  padding: 16px 20px;

}



.log div {

  padding: 4px 0;

  color: var(--text-3);

}



.log .err {

  color: var(--fail);

}

.log .ok {

  color: var(--pass);

}



/* Overview creative layout */

.hero-panel {

  position: relative;

  overflow: hidden;

  padding: 28px;

  background:

    radial-gradient(ellipse 80% 120% at 100% 0%, rgba(255, 106, 61, 0.18), transparent 55%),

    linear-gradient(135deg, #0a0a0a 0%, #111111 45%, #1a1210 100%);

  color: #fff;

  border: 0;

  box-shadow: 0 18px 40px -24px rgba(21, 32, 45, 0.65);

}



.hero-copy {

  margin-left: 12px;

}



.hero-panel h2 {

  margin: 0;

  font-size: 30px;

  font-weight: 750;

  letter-spacing: -0.03em;

  color: #fff;

}



.hero-panel p {

  margin: 10px 0 0;

  color: rgba(226, 232, 240, 0.78);

  font-size: 15px;

  max-width: 520px;

}



.hero-actions {

  display: flex;

  flex-wrap: nowrap;

  gap: 10px;

  margin-top: 20px;

  align-items: center;

}



.hero-actions .btn,

.hero-actions .btn-ghost {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  height: 44px;

  line-height: 1;

  padding: 0 18px;

  border-radius: 10px;

  font-size: 15px;

  font-weight: 650;

  white-space: nowrap;

  flex-shrink: 0;

  box-sizing: border-box;

}



.hero-actions .btn-primary {

  background: linear-gradient(135deg, #ff6a3d, #ff8a4c);

  box-shadow: 0 12px 28px -10px rgba(255, 106, 61, 0.85);

  color: #fff;

}



.hero-actions .btn-primary:hover {

  filter: brightness(1.06);

  background: linear-gradient(135deg, #ff6a3d, #ff8a4c);

}



.hero-actions .btn-ghost {

  border: 1px solid rgba(255, 138, 76, 0.55);

  color: #ff8a4c;

  background: rgba(255, 106, 61, 0.1);

}



.hero-actions .btn-ghost:hover {

  background: rgba(255, 106, 61, 0.2);

  color: #ffb087;

  border-color: #ff8a4c;

}



.stat-grid {

  display: grid;

  gap: 14px;

  grid-template-columns: repeat(2, minmax(0, 1fr));

}



@media (min-width: 900px) {

  .stat-grid {

    grid-template-columns: repeat(4, minmax(0, 1fr));

  }

}



.stat-card {

  position: relative;

  overflow: hidden;

  padding: 14px 16px 12px;

  border-radius: 12px;

  border: 1px solid var(--border);

  background: var(--surface);

  box-shadow: var(--shadow);

}



.stat-card::after {

  content: "";

  position: absolute;

  right: -20px;

  top: -24px;

  width: 78px;

  height: 78px;

  border-radius: 50%;

  opacity: 0.16;

  background: currentColor;

}



.stat-card .label {

  margin: 0;

  font-size: 11px;

  font-weight: 700;

  letter-spacing: 0.08em;

  text-transform: uppercase;

  color: var(--text-4);

}



.stat-card .value {

  margin: 8px 0 0;

  font-size: 28px;

  font-weight: 750;

  letter-spacing: -0.03em;

  color: var(--text);

  font-variant-numeric: tabular-nums;

}



.stat-card .hint {

  margin: 8px 0 0;

  font-size: 13px;

  color: var(--text-4);

}



.stat-card.tone-indigo { color: var(--aa-orange-dark); }

.stat-card.tone-indigo .value { color: var(--aa-orange); }

.stat-card.tone-teal { color: var(--aa-orange-dark); }

.stat-card.tone-teal .value { color: var(--aa-orange); }

.stat-card.tone-blue { color: var(--aa-orange-dark); }

.stat-card.tone-blue .value { color: var(--aa-orange); }



.legend {

  display: flex;

  flex-wrap: wrap;

  gap: 12px;

  font-size: 12px;

  color: var(--text-4);

  font-weight: 600;

}



.legend i {

  display: inline-block;

  width: 10px;

  height: 10px;

  border-radius: 3px;

  margin-right: 6px;

  vertical-align: -1px;

}



.stage-list {

  display: flex;

  flex-wrap: wrap;

  gap: 8px;

  padding: 16px 20px 20px;

}



.stage {

  padding: 8px 12px;

  border-radius: 999px;

  border: 1px solid var(--border);

  font-size: 13px;

  color: var(--text-3);

  background: var(--surface-2);

  white-space: nowrap;

}



.stage.done {

  border-color: #ffd2bf;

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

}

.stage.running {

  border-color: #f5d48a;

  background: var(--info-soft);

  color: #9a6b0a;

}

.stage.failed {

  border-color: rgba(159, 18, 57, 0.3);

  background: rgba(159, 18, 57, 0.1);

  color: #9f1239;

}



.preset {

  text-align: left;

  padding: 16px;

  border-radius: 12px;

  border: 1px solid var(--border);

  background: var(--surface-2);

  transition: 0.15s ease;

  width: 100%;

}



.preset:hover,

.preset.on {

  border-color: #ffd2bf;

  background: var(--aa-orange-soft);

}



.preset strong {

  display: block;

  color: var(--text);

  font-size: 15px;

}



.preset span {

  display: block;

  margin-top: 6px;

  color: var(--text-4);

  font-size: 13px;

}



.prev-runs {

  display: flex;

  flex-direction: column;

  gap: 8px;

  padding: 12px;

  max-height: min(62vh, 560px);

  overflow: auto;

}



.prev-run {

  display: flex;

  flex-direction: column;

  gap: 10px;

  padding: 12px 14px;

  border: 1px solid var(--border);

  border-radius: 12px;

  background: var(--surface-2);

  text-decoration: none;

  color: inherit;

  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;

}



.prev-run:hover {

  border-color: #ffd2bf;

  background: #fffaf7;

  box-shadow: 0 4px 14px rgba(26, 29, 38, 0.06);

}



.prev-run-top {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  min-width: 0;

}



.prev-run-top strong {

  color: var(--text);

  font-size: 14px;

  font-weight: 700;

  white-space: nowrap;

}



.prev-run-top .badge {

  flex-shrink: 0;

}



.prev-run-file {

  display: block;

  color: var(--text-3);

  font-size: 12px;

  line-height: 1.35;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;

}



.prev-run-foot {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  min-width: 0;

}



.prev-run-stats {

  display: flex;

  flex-wrap: wrap;

  gap: 8px;

  min-width: 0;

}



.prev-run-stat {

  display: inline-flex;

  align-items: center;

  gap: 4px;

  padding: 3px 8px;

  border-radius: 999px;

  background: #fff;

  border: 1px solid var(--border);

  font-size: 11px;

  font-weight: 650;

  color: var(--text-3);

  white-space: nowrap;

}



.prev-run-stat em {

  font-style: normal;

  color: var(--text);

  font-variant-numeric: tabular-nums;

}



.prev-run-stat.ok em {

  color: var(--aa-orange-dark);

}



.prev-run-stat.bad em {

  color: var(--fail);

}



.prev-run-stat.run em {

  color: #9a6b0a;

}



.prev-run-time {

  color: var(--text-4);

  font-size: 11px;

  white-space: nowrap;

  flex-shrink: 0;

}



.pass-rate-inline {

  display: inline-flex;

  align-items: center;

  gap: 10px;

  min-width: 160px;

}



.pass-rate-inline .progress {

  width: 88px;

  flex-shrink: 0;

}



.pass-rate-inline strong {

  color: var(--text);

  font-size: 14px;

  font-variant-numeric: tabular-nums;

}



.pass-rate-inline .muted {

  font-size: 12px;

  font-weight: 600;

  text-transform: uppercase;

  letter-spacing: 0.03em;

}



.chip {

  display: inline-block;

  margin: 3px;

  padding: 6px 10px;

  border-radius: 8px;

  background: var(--aa-orange-soft);

  font-size: 12px;

  color: var(--aa-orange-dark);

  white-space: nowrap;

}



#catalog-drawer-root {

  position: fixed;

  inset: 0;

  z-index: 20000;

}



.drawer-bg {

  position: absolute;

  inset: 0;

  background: rgba(26, 29, 38, 0.18);

  z-index: 1;

  opacity: 0;

  transition: opacity 0.28s ease;

}



.drawer-bg.is-open {

  opacity: 1;

}



.drawer {

  position: absolute;

  top: 0;

  right: 0;

  bottom: 0;

  width: min(560px, 100%);

  background: var(--surface);

  border-left: 1px solid var(--border);

  z-index: 2;

  display: flex;

  flex-direction: column;

  box-shadow: -16px 0 48px rgba(26, 29, 38, 0.16);

  transform: translateX(100%);

  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);

}



.drawer.is-open {

  transform: translateX(0);

}



.drawer-hd,

.drawer-ft {

  padding: 20px;

  border-bottom: 1px solid var(--border);

}



.drawer-hd {

  position: relative;

  padding-left: 56px;

}



.drawer-close-x {

  position: absolute;

  top: 22px;

  left: 12px;

  z-index: 3;

  width: 36px;

  height: 36px;

  border-radius: 8px;

  border: 1px solid var(--border);

  background: #ffffff;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  color: var(--text);

}



.drawer-close-x svg {

  width: 18px;

  height: 18px;

}



.drawer-close-x:hover {

  background: var(--surface-2);

  color: var(--text);

}



.drawer-ft {

  border-bottom: 0;

  border-top: 1px solid var(--border);

  display: flex;

  justify-content: flex-end;

  gap: 10px;

  flex-wrap: wrap;

}





#page-catalog table tbody tr {

  cursor: pointer;

}

#page-catalog table tbody tr:hover {

  background: var(--aa-orange-soft);

}

.drawer-bd {

  flex: 1;

  overflow: auto;

  padding: 20px;

}



.folder-btn {

  width: 100%;

  display: flex;

  align-items: flex-start;

  gap: 10px;

  text-align: left;

  padding: 12px;

  border-radius: 10px;

  color: var(--text-3);

  font-size: 14px;

}



.folder-btn .folder-ico {

  width: 20px;

  height: 20px;

  flex-shrink: 0;

  margin-top: 1px;

  color: var(--aa-orange);

}



.folder-btn:hover,

.folder-btn.on {

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

}



.ev-folder-list {

  padding-top: 8px;

  display: flex;

  flex-direction: column;

  gap: 4px;

  max-height: 64vh;

  overflow: auto;

}



.folder-grid {

  display: grid;

  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));

  gap: 12px;

}



.case-folder {

  text-align: left;

  padding: 16px;

  border-radius: 12px;

  border: 1px solid var(--border);

  background: var(--surface-2);

  width: 100%;

}



.case-folder:hover,

.case-folder:focus-visible {

  border-color: #ffd2bf;

  background: var(--aa-orange-soft);

}



.case-folder-hd {

  display: flex;

  justify-content: space-between;

  align-items: center;

  gap: 8px;

  margin-bottom: 8px;

  flex-wrap: wrap;

}



.folder-glyph {

  display: block;

  width: 42px;

  height: 30px;

  margin-bottom: 12px;

  background: linear-gradient(180deg, #ff8a4c, var(--aa-orange));

  border-radius: 0 6px 6px 6px;

  position: relative;

  box-shadow: 0 6px 12px -8px rgba(226, 85, 43, 0.8);

}



.folder-glyph::before {

  content: "";

  position: absolute;

  top: -7px;

  left: 0;

  width: 18px;

  height: 10px;

  background: var(--aa-coral);

  border-radius: 4px 4px 0 0;

}



.crumb {

  display: flex;

  flex-wrap: wrap;

  align-items: center;

  gap: 6px;

  margin-top: 6px;

  font-size: 12px;

  color: var(--text-4);

  font-family: var(--mono);

}



.crumb button {

  color: var(--aa-orange-dark);

  font-weight: 650;

}



.crumb button:hover {

  text-decoration: underline;

}



.shot-grid {

  display: grid;

  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));

  gap: 12px;

}



.shot {

  width: 100%;

  text-align: left;

  border: 1px solid var(--border);

  border-radius: 12px;

  overflow: hidden;

  background: #fff;

}



.shot:hover,

.shot.on {

  border-color: #ffd2bf;

  box-shadow: 0 8px 18px -12px rgba(226, 85, 43, 0.7);

}



.shot-meta {

  padding: 10px 12px 12px;

  display: flex;

  flex-direction: column;

  gap: 6px;

}



.shot-meta strong {

  font-size: 12px;

  font-family: var(--mono);

  color: var(--text);

  word-break: break-all;

}



.shot-meta span {

  display: flex;

  align-items: center;

  gap: 8px;

  flex-wrap: wrap;

  font-size: 11px;

  color: var(--text-4);

}



.shot-frame {

  background: #f3f5f9;

  border-bottom: 1px solid var(--border);

}



.shot-chrome {

  display: flex;

  align-items: center;

  gap: 8px;

  height: 26px;

  padding: 0 10px;

  background: linear-gradient(90deg, #ff6a3d, #ff8a4c);

  color: #fff;

  font-size: 10px;

  font-weight: 650;

}



.shot-dots {

  width: 28px;

  height: 6px;

  border-radius: 99px;

  background: rgba(255, 255, 255, 0.55);

}



.shot-canvas {

  padding: 10px 12px 12px;

  min-height: 92px;

}



.shot-frame.lg .shot-canvas {

  min-height: 280px;

  padding: 20px 24px 24px;

}



.shot-frame.lg .shot-chrome {

  height: 36px;

  font-size: 13px;

}



.shot-title {

  font-size: 12px;

  font-weight: 650;

  color: var(--text);

  margin-bottom: 8px;

}



.shot-frame.lg .shot-title {

  font-size: 18px;

  margin-bottom: 14px;

}



.shot-rows {

  display: grid;

  gap: 6px;

}



.shot-rows i {

  display: block;

  height: 8px;

  border-radius: 4px;

  background: #e4e8f0;

}



.shot-rows i:nth-child(1) { width: 78%; }

.shot-rows i:nth-child(2) { width: 62%; }

.shot-rows i:nth-child(3) { width: 48%; }



.shot-frame.lg .shot-rows i {

  height: 14px;

}



.shot-alert {

  margin-top: 8px;

  padding: 6px 8px;

  border-radius: 6px;

  background: rgba(159, 18, 57, 0.1);

  color: #9f1239;

  font-size: 10px;

  line-height: 1.4;

}



.shot-frame.lg .shot-alert {

  margin-top: 16px;

  padding: 12px 14px;

  font-size: 14px;

}



.shot-live {

  margin-top: 8px;

  color: #9a6b0a;

  font-size: 11px;

  font-weight: 650;

}



.shot-frame.fail .shot-chrome {

  background: linear-gradient(90deg, #9f1239, #be185d);

}



.shot-lightbox {

  position: fixed;

  inset: 0;

  z-index: 80;

  background: rgba(18, 22, 32, 0.55);

  display: grid;

  place-items: center;

  padding: 24px;

}



.shot-lightbox-card {

  width: min(820px, 100%);

  background: #fff;

  border-radius: 16px;

  overflow: hidden;

  box-shadow: 0 24px 60px rgba(18, 22, 32, 0.28);

}



.card-btn {

  text-align: left;

  padding: 16px;

  border-radius: 12px;

  border: 1px solid var(--border);

  background: var(--surface-2);

  width: 100%;

}



.card-btn.on,

.card-btn:hover {

  border-color: #ffd2bf;

  background: var(--aa-orange-soft);

}



@media (max-width: 720px) {

  .content {

    padding: 10px 8px;

  }

  .page-hd h2 {

    font-size: 22px;

  }

  .stat .value {

    font-size: 26px;

  }

  .topbar {

    padding: 10px 10px;

  }

}



/* Login — plain white + modern card */

.login-body {

  min-height: 100%;

  height: 100%;

  margin: 0;

  background: #ffffff;

  color: var(--text);

}



.login-shell {

  min-height: 100%;

  height: 100%;

  display: grid;

  place-items: center;

  padding: 16px;

  box-sizing: border-box;

}



.login-card {

  width: 100%;

  max-width: 340px;

  background: #fff;

  border: 1px solid #e8ebf2;

  border-radius: 16px;

  padding: 0 28px 24px;

  overflow: hidden;

  box-shadow:

    0 1px 2px rgba(26, 29, 38, 0.04),

    0 18px 40px -20px rgba(26, 29, 38, 0.18);

  animation: loginRise 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;

}



.login-banner {

  height: 8px;

  margin: 0 -28px 28px;

  background: linear-gradient(90deg, #ff8a4c 0%, var(--aa-orange) 50%, var(--aa-orange-dark) 100%);

}



.login-brand {

  display: flex;

  align-items: center;

  gap: 10px;

  margin-bottom: 20px;

}



.login-brand strong {

  display: block;

  font-size: 11px;

  font-weight: 800;

  color: var(--text);

  line-height: 1.1;

}



.login-brand span {

  display: block;

  font-size: 14px;

  font-weight: 750;

  color: var(--aa-orange-dark);

  line-height: 1.1;

  margin-top: 0;

}



.login-card h1 {

  margin: 0;

  font-size: 22px;

  font-weight: 750;

  letter-spacing: -0.03em;

  color: var(--text);

}



.login-sub {

  margin: 8px 0 0;

  color: var(--text-3);

  font-size: 13px;

  line-height: 1.5;

}



.login-form {

  margin-top: 20px;

  display: flex;

  flex-direction: column;

  gap: 10px;

}



.login-form input {

  height: 42px;

  width: 100%;

  padding: 0 12px;

  border-radius: 10px;

  border: 1px solid var(--border-strong);

  background: #fafbfc;

  color: var(--text);

  font-size: 14px;

  font-weight: 550;

  outline: none;

  transition: 0.15s ease;

}



.login-form input::placeholder {

  color: var(--text-4);

  font-weight: 500;

}



.login-form input:focus {

  border-color: var(--aa-orange);

  background: #fff;

  box-shadow: 0 0 0 3px rgba(255, 106, 61, 0.12);

}



.login-btn {

  width: 100%;

  height: 42px;

  margin-top: 4px;

  border-radius: 12px;

}



.login-btn:hover {

  filter: brightness(1.04);

}



.login-foot {

  margin: 22px 0 0;

  text-align: center;

  font-size: 12px;

  color: var(--text-4);

  font-weight: 600;

}



@keyframes loginRise {

  from {

    opacity: 0;

    transform: translateY(10px);

  }

  to {

    opacity: 1;

    transform: none;

  }

}



/* Nav buttons (same look as original <a> nav links) */
.nav .nav-btn,
.mobile-nav .nav-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 12px 14px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--text-3);
  font: inherit;
  font-size: 15px;
  font-weight: 550;
  text-align: left;
  cursor: pointer;
  transition: 0.15s ease;
  position: relative;
  white-space: nowrap;
}
.nav .nav-btn:hover,
.mobile-nav .nav-btn:hover {
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
}
.nav .nav-btn.active,
.mobile-nav .nav-btn.active {
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
  font-weight: 650;
}
.nav .nav-btn.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 20px;
  border-radius: 0 4px 4px 0;
  background: var(--aa-orange);
}
.nav .nav-btn:hover .nav-icon,
.nav .nav-btn.active .nav-icon,
.mobile-nav .nav-btn:hover .nav-icon,
.mobile-nav .nav-btn.active .nav-icon {
  opacity: 1;
}

.mobile-nav .nav-btn {
  width: auto;
  flex: 0 0 auto;
}

/* Restore spacing: page roots are .stack; keep gap even if flex gap is odd in iframe */
.stack > * + * {
  margin-top: 0; /* gap handles spacing when supported */
}
@supports not (gap: 20px) {
  .stack > * + * {
    margin-top: 20px;
  }
}

/* Appsmith Custom Widget viewport — fill iframe only; never grow past it */
html, body {
  height: 100% !important;
  min-height: 100% !important;
  max-height: 100% !important;
  width: 100%;
  max-width: 100%;
  overflow: hidden !important;
  margin: 0;
}
#root {
  height: 100% !important;
  min-height: 100% !important;
  max-height: 100% !important;
  width: 100%;
  max-width: 100%;
  overflow: hidden !important;
  background: var(--bg);
  box-sizing: border-box;
}
#root .app {
  min-height: 100% !important;
  height: 100% !important;
  max-height: 100% !important;
  width: 100%;
  max-width: 100%;
  overflow: hidden !important;
}
/* Always show desktop sidebar inside the widget (iframe width can be < 960) */
#root .sidebar {
  display: flex !important;
  height: 100% !important;
  position: relative;
  top: auto;
  flex-shrink: 0;
}
#root .mobile-nav {
  display: none !important;
}
#root .main-wrap {
  height: 100%;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
#root .content {
  flex: 1;
  overflow: auto;
  min-height: 0;
  min-width: 0;
  max-width: 100%;
  width: 100%;
  padding: 12px 10px !important;
  margin: 0 !important;
  box-sizing: border-box;
}
#root .topbar {
  padding-left: 12px !important;
  padding-right: 12px !important;
}
#root .app,
#root .main-wrap,
#root #view-app:not([hidden]) {
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 !important;
}
#root .page-panel,
#root .stack,
#root .grid-2,
#root .overview-split,
#root .overview-side,
#root .panel {
  min-width: 0;
  max-width: 100%;
}
#root .scroll {
  max-width: 100%;
  overflow-x: auto;
}
#root .filters {
  grid-template-columns: minmax(0, 1.5fr) repeat(3, minmax(0, 1fr));
}
@media (max-width: 900px) {
  #root .filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
#root .catalog-actions {
  flex-wrap: wrap;
  max-width: 100%;
}
#root .login-body,
#root .login-shell {
  min-height: 100% !important;
  height: 100% !important;
  max-height: 100% !important;
  overflow: auto;
  box-sizing: border-box;
}
#root #view-login:not([hidden]),
#root #view-app:not([hidden]) {
  height: 100% !important;
  min-height: 100% !important;
  max-height: 100% !important;
}
#root .page-panel[hidden],
#root #view-login[hidden],
#root #view-app[hidden] {
  display: none !important;
}
#root .page-panel:not([hidden]) {
  display: block;
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
}




