  transition:
    transform 0.45s cubic-bezier(0.4, 0.05, 0.2, 1),
    opacity 0.35s ease 0.05s,
    border-radius 0.35s ease;
  transform: translate(calc(-50% + var(--min-x, 0px)), calc(-50% + var(--min-y, 0px))) scale(var(--min-scale, 0.08));
  opacity: 0;
  border-radius: 999px;
  pointer-events: none;
  overflow: hidden;
}

#bot-run-modal-root .sn-modal-bg.is-minimizing {
  transition: opacity 0.28s ease;
  opacity: 0;
  pointer-events: none;
}

@keyframes bot-status-catch {
  0% { transform: scale(1); }
  35% { transform: scale(1.14); }
  100% { transform: scale(1); }
}

