/* =========================================================
   DATA
   ========================================================= */
/* Sample data for the Workday Functional Test Agent UI */

window.APP_DATA = {
  approvedError:
    "The base salary entered is below the salary range minimum for this role. Action Required: Please update the base salary to meet or exceed the salary range minimum before proceeding.",

  stepCatalog: [
    "Connect to SharePoint",
    "Download input file",
    "Read input Excel",
    "Find BMS worker ID",
    "Login to Workday",
    "Proxy as initiator",
    "Open compensation process",
    "Enter below-min base salary",
    "Validate hard-stop message",
    "Correct salary and submit",
    "Complete approval route",
    "Stop proxy / upload evidence",
  ],

  exceptionMatrix: [
    { ref: "1.1", type: "Business", scenario: "Expected result not matched", action: "Stop test case, continue batch", notify: "Business" },
    { ref: "1.2", type: "Business", scenario: "Unable to find matching BMS ID", action: "Stop test case, continue batch", notify: "Business" },
    { ref: "1.3", type: "Business", scenario: "Restart required mid-case", action: "Stop test case, mark for retry", notify: "Business" },
    { ref: "2.1", type: "System", scenario: "Credentials expired / unavailable", action: "Stop batch, notify teams", notify: "IT, Business" },
    { ref: "2.2", type: "System", scenario: "Application unavailable", action: "Stop batch, notify teams", notify: "IT, Business" },
  ],

  systems: [
    { name: "Workday", type: "Website / API", third: "Yes", access: "Credential", note: "Sandbox Preview tenant" },
    { name: "ServiceNow", type: "Website / API", third: "Yes", access: "OAuth / Table API", note: "Agile Development stories (rm_story)" },
    { name: "SharePoint", type: "Website / API", third: "Yes", access: "Credential", note: "Input / output folders" },
    { name: "Automation Anywhere A360", type: "Control Room", third: "No", access: "Credential", note: "Unattended bot runners" },
    { name: "Reporting database", type: "Database", third: "No", access: "Credential", note: "Stores run history and results" },
    { name: "Outlook", type: "Windows App", third: "No", access: "Credential", note: "Exception notifications" },
  ],

  /* ServiceNow Agile Development (rm_story) — structure ready for Table API binding */
  snow: {
    instance: "https://dev12345.service-now.com",
    table: "rm_story",
    lastSyncedAt: null,
    stories: [],
  },

  schemaTables: [
    { name: "Runs", rows: 0, purpose: "Each uploaded workbook and overall run" },
    { name: "Test cases", rows: 0, purpose: "Individual scenarios in a run" },
    { name: "Summaries", rows: 0, purpose: "Pass and fail totals by process" },
    { name: "Executions", rows: 0, purpose: "Bot runner attempts" },
    { name: "Steps", rows: 0, purpose: "Step-by-step progress" },
    { name: "Exceptions", rows: 0, purpose: "Business and system issues" },
  ],

  batches: [],
  staging: [],
  metrics: [],
  executions: [],
  steps: [],
  errors: [],
};

(function seed() {
  const processes = ["Request Compensation Change", "Propose Job Change"];
  const scenarios = ["Salary Below Minimum Range", "Hard Stop Validation"];
  const initiators = [
    "Employee Data Processor",
    "HRS Initiator",
    "HR Initiator",
    "Manager",
    "Global Processor",
    "Compensation Processor",
  ];
  const sites = [
    { region: "Americas", country: "USA", location: "New Brunswick - NJ" },
    { region: "Americas", country: "USA", location: "Cambridge Crossing - MA" },
    { region: "EMEA", country: "United Kingdom", location: "Uxbridge" },
    { region: "EMEA", country: "Netherlands", location: "Leiden" },
    { region: "APAC", country: "India", location: "Hyderabad" },
    { region: "APAC", country: "Japan", location: "Otemachi" },
  ];
  const workers = ["00351783", "00544802", "00528485", "00494212", "00587102", "00308156", "00494806", "00238095"];
  const salaryTypes = ["Full time / Salary", "Part time / Salary", "Full time / Hourly", "Full time / Annual"];
  const runners = ["BOT-RUNNER-01", "BOT-RUNNER-02", "BOT-RUNNER-03"];

  const batches = [];
  const staging = [];
  const metrics = [];
  const executions = [];
  const steps = [];
  const errors = [];

  let stagingId = 1000;
  let executionId = 5000;
  let stepId = 9000;
  let errorId = 7000;
  let summaryId = 3000;

  for (let b = 0; b < 8; b++) {
    const batchId = 100 + b;
    const day = 14 - b;
    const totalCases = 10 + (b % 4);
    const failed = b % 3 === 0 ? 2 : b % 4 === 0 ? 1 : 0;
    const inProgress = b === 0 ? 1 : 0;
    const passed = totalCases - failed - inProgress;
    const started = `2026-09-${String(day).padStart(2, "0")}T09:00:00+05:30`;
    const ended = b === 0 ? null : `2026-09-${String(day).padStart(2, "0")}T10:${String(15 + b).padStart(2, "0")}:00+05:30`;

    batches.push({
      batch_id: batchId,
      source_file_name: `UAT_TEST_EXECUTION_SCRIPT_09${String(day).padStart(2, "0")}.xlsx`,
      uploaded_by: b % 2 === 0 ? "B. Deep" : "Control Room Scheduler",
      uploaded_at: `2026-09-${String(day).padStart(2, "0")}T08:45:00+05:30`,
      run_started_at: started,
      run_ended_at: ended,
      overall_status: b === 0 ? "Running" : failed ? "CompletedWithErrors" : "Completed",
      total_test_cases: totalCases,
      total_business_processes: 2,
      comments: b === 0 ? "Live Phase 1 hard-stop validation" : "Scheduled 09:00 Control Room run",
      created_at: started,
      updated_at: ended || started,
      passed_count: passed,
      failed_count: failed,
      in_progress_count: inProgress,
    });

    // metrics by process/scenario
    processes.forEach((processName, pi) => {
      const slice = Math.floor(totalCases / 2) + (pi === 0 ? totalCases % 2 : 0);
      const f = pi === 0 ? Math.min(failed, slice) : Math.max(0, failed - Math.min(failed, Math.floor(totalCases / 2)));
      const ip = pi === 0 ? inProgress : 0;
      const p = slice - f - ip;
      metrics.push({
        summary_id: summaryId++,
        batch_id: batchId,
        process_name: processName,
        scenario_name: scenarios[0],
        total_count: slice,
        passed_count: p,
        failed_count: f,
        in_progress_count: ip,
        avg_retry_count: Number((f * 0.5).toFixed(2)),
        comments: null,
        last_updated_at: ended || started,
      });
    });

    for (let i = 0; i < totalCases; i++) {
      const sid = stagingId++;
      const site = sites[i % sites.length];
      const processName = processes[i % 2];
      const initiator = initiators[i % initiators.length];
      let status = "Passed";
      if (i < failed) status = "Failed";
      else if (i < failed + inProgress) status = "InProgress";

      const row = {
        staging_id: sid,
        batch_id: batchId,
        process_name: processName,
        scenario_name: scenarios[0],
        test_case_name: `TC-${String(i + 1).padStart(2, "0")} Hard Stop Validation`,
        workday_instance: "Sandbox Preview",
        initiator,
        bms_worker_id: workers[i % workers.length],
        task: processName,
        region: site.region,
        country: site.country,
        location: site.location,
        salary_type: salaryTypes[i % salaryTypes.length],
        frequency: "Annual",
        pay_type: "Salary",
        effective_date: "2026-10-01",
        reason_selection: "Lateral Move - Different Role/Responsibilities",
        change_justification: "UAT hard-stop validation",
        test_to_run: "Base salary below minimum range",
        test_steps: APP_DATA.stepCatalog.join(" | "),
        expected_result: APP_DATA.approvedError,
        requires_approval: 1,
        input_data: JSON.stringify({ below_min: true, currency: site.country === "USA" ? "USD" : "LOCAL" }),
        status,
        attempt_number: 1,
        retry_count: status === "Failed" ? 1 : 0,
        is_retried_flag: status === "Failed" ? 1 : 0,
        original_batch_id: status === "Failed" && b > 2 ? batchId - 1 : null,
        created_at: started,
        updated_at: ended || started,
        started_at: started,
        completed_at: status === "InProgress" ? null : ended || started,
      };
      staging.push(row);

      const eid = executionId++;
      const runner = runners[i % runners.length];
      executions.push({
        execution_id: eid,
        staging_id: sid,
        bot_runner_id: runner,
        status: status === "Passed" ? "Passed" : status === "Failed" ? "Failed" : "Running",
        started_at: started,
        ended_at: status === "InProgress" ? null : ended || started,
        last_heartbeat_at: `2026-09-${String(day).padStart(2, "0")}T09:${String(5 + i).padStart(2, "0")}:00+05:30`,
        comments: null,
        created_at: started,
        duration_sec: 160 + i * 18,
        screenshots: 5 + (i % 4),
      });

      APP_DATA.stepCatalog.forEach((stepName, si) => {
        let stepStatus = "Passed";
        if (status === "InProgress") stepStatus = si < 5 ? "Passed" : si === 5 ? "Running" : "Pending";
        if (status === "Failed" && si >= 8) stepStatus = si === 8 ? "Failed" : "Skipped";
        const stepExecId = stepId++;
        steps.push({
          step_execution_id: stepExecId,
          staging_id: sid,
          execution_id: eid,
          step_sequence: si + 1,
          step_name: stepName,
          step_status: stepStatus,
          step_start_time: started,
          step_end_time: stepStatus === "Running" || stepStatus === "Pending" ? null : started,
          error_message: stepStatus === "Failed" ? "Hard-stop text mismatch vs approved message" : null,
          log_reference: `log/${batchId}/${sid}/step-${si + 1}`,
          comments: null,
          created_at: started,
        });

        if (stepStatus === "Failed") {
          errors.push({
            error_id: errorId++,
            staging_id: sid,
            step_execution_id: stepExecId,
            exception_type: "Business",
            error_code: "BE-1.1",
            error_message: "Error text mismatch - displayed message deviates from the approved wording",
            stack_trace: `BaseSalaryTest.validateMessage()\n  at step_sequence=${si + 1}\n  staging_id=${sid}`,
            occurred_at: started,
            comments: "Captured for SME review",
            created_at: started,
          });
        }
      });

      if (status === "Failed" && i % 2 === 1) {
        errors.push({
          error_id: errorId++,
          staging_id: sid,
          step_execution_id: null,
          exception_type: "System",
          error_code: "SE-2.2",
          error_message: "Workday session timed out while awaiting approval route",
          stack_trace: `ApprovalRouteAgent.waitForRender()\n  staging_id=${sid}`,
          occurred_at: started,
          comments: null,
          created_at: started,
        });
      }
    }
  }

  // Catalog view = distinct staging blueprints (latest batch template rows)
  const catalog = [];
  for (let i = 0; i < 24; i++) {
    const site = sites[i % sites.length];
    catalog.push({
      staging_id: 10 + i,
      batch_id: null,
      process_name: processes[i % 2],
      scenario_name: scenarios[0],
      test_case_name: `TC-${String(i + 1).padStart(2, "0")} Hard Stop Validation`,
      workday_instance: "Sandbox Preview",
      initiator: initiators[i % initiators.length],
      bms_worker_id: workers[i % workers.length],
      task: processes[i % 2],
      region: site.region,
      country: site.country,
      location: site.location,
      salary_type: salaryTypes[i % salaryTypes.length],
      frequency: "Annual",
      pay_type: "Salary",
