window.Utils = {
  fmtDuration(sec) {
    if (!sec && sec !== 0) return "—";
    const m = Math.floor(sec / 60);
    const s = Math.round(sec % 60);
    return m ? `${m}m ${String(s).padStart(2, "0")}s` : `${s}s`;
  },

  fmtTime(iso) {
    if (!iso) return "—";
    return new Date(iso).toLocaleString("en-GB", {
      day: "2-digit",
      month: "short",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });
  },

  money(v, ccy) {
    return `${ccy} ${Number(v).toLocaleString("en-US")}`;
  },

  resultTone(result) {
    if (result === "Pass" || result === "Passed") return "pass";
    if (result === "Fail" || result === "Failed") return "fail";
    if (result === "Blocked") return "warn";
    if (result === "Running" || result === "InProgress") return "info";
    return "neutral";
  },

  qs(name) {
    if (window.AppRouter && typeof window.AppRouter.getQuery === "function") {
      const fromRouter = window.AppRouter.getQuery(name);
      if (fromRouter != null && fromRouter !== "") return fromRouter;
    }
    const fromSearch = new URLSearchParams(location.search || "").get(name);
    if (fromSearch != null && fromSearch !== "") return fromSearch;
    const hash = (location.hash || "").replace(/^#/, "");
    const q = hash.includes("?") ? hash.split("?")[1] : "";
    return new URLSearchParams(q).get(name);
  },

  progress(value, tone) {
    const pct = Math.max(0, Math.min(100, Math.round(value * 100)));
    return `<div class="progress ${tone || ""}"><span style="width:${pct}%"></span></div>`;
  },

  badge(text, tone) {
    return `<span class="badge ${tone || "neutral"}">${text}</span>`;
  },

  enhanceSelects(scope) {
    const root = scope || document;
    if (!window.__ddDocBound) {
      window.__ddDocBound = true;
      document.addEventListener("click", (e) => {
        if (e.target.closest(".dd")) return;
        document.querySelectorAll(".dd.is-open").forEach((el) => {
          el.classList.remove("is-open");
          const menu = el.querySelector(".dd-menu");
          if (menu) menu.hidden = true;
          const trigger = el.querySelector(".dd-trigger");
          if (trigger) trigger.setAttribute("aria-expanded", "false");
        });
      });
      document.addEventListener("keydown", (e) => {
        if (e.key !== "Escape") return;
        document.querySelectorAll(".dd.is-open").forEach((el) => {
          el.classList.remove("is-open");
          const menu = el.querySelector(".dd-menu");
          if (menu) menu.hidden = true;
        });
      });
    }

    root.querySelectorAll("select").forEach((select) => {
      if (select.dataset.ddReady === "1") return;
      if (select.closest(".dd")) return;

      select.dataset.ddReady = "1";
      const wrap = document.createElement("div");
      wrap.className = "dd";
      select.parentNode.insertBefore(wrap, select);
      wrap.appendChild(select);
      select.classList.add("dd-native");
      select.setAttribute("tabindex", "-1");
      select.setAttribute("aria-hidden", "true");

      const trigger = document.createElement("button");
      trigger.type = "button";
      trigger.className = "dd-trigger";
      trigger.setAttribute("aria-haspopup", "listbox");
      trigger.setAttribute("aria-expanded", "false");
      trigger.innerHTML = `<span class="dd-label"></span><span class="dd-caret" aria-hidden="true"></span>`;

      const menu = document.createElement("div");
      menu.className = "dd-menu";
      menu.setAttribute("role", "listbox");
      menu.hidden = true;

      wrap.appendChild(trigger);
      wrap.appendChild(menu);

      const sync = () => {
        const opt = select.options[select.selectedIndex];
        trigger.querySelector(".dd-label").textContent = opt ? opt.textContent : "Select…";
        menu.innerHTML = [...select.options]
          .map(
            (o, i) =>
              `<button type="button" class="dd-option${o.selected ? " is-selected" : ""}" data-idx="${i}" role="option" aria-selected="${o.selected ? "true" : "false"}"><span class="dd-option-label">${o.textContent}</span></button>`,
          )
          .join("");
      };

      const close = () => {
        wrap.classList.remove("is-open");
        menu.hidden = true;
        trigger.setAttribute("aria-expanded", "false");
      };

      const open = () => {
        document.querySelectorAll(".dd.is-open").forEach((el) => {
          if (el === wrap) return;
          el.classList.remove("is-open");
          const m = el.querySelector(".dd-menu");
          if (m) m.hidden = true;
          const t = el.querySelector(".dd-trigger");
          if (t) t.setAttribute("aria-expanded", "false");
        });
        wrap.classList.add("is-open");
        menu.hidden = false;
        trigger.setAttribute("aria-expanded", "true");
      };

      sync();

      trigger.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (wrap.classList.contains("is-open")) close();
        else open();
      });

      menu.addEventListener("click", (e) => {
        const btn = e.target.closest(".dd-option");
        if (!btn) return;
        e.preventDefault();
        e.stopPropagation();
        const idx = Number(btn.dataset.idx);
        if (!Number.isNaN(idx)) {
          select.selectedIndex = idx;
          select.dispatchEvent(new Event("change", { bubbles: true }));
          sync();
        }
        close();
      });
    });
  },
};


/* =========================================================
   BOT RUNNER — shared run modal + topbar status
   ========================================================= */
window.BotRunner = {
  job: null,
  timer: null,
  minimized: false,

  isActive() {
    return !!(this.job && (this.job.status === "running" || this.job.status === "done"));
  },

  start(opts) {
    const steps = (opts.steps || []).filter(Boolean);
    if (!steps.length) return;

    this.stopTimer();
    this.job = {
      id: "run-" + Date.now(),
      title: opts.title || "Bot run",
      source: opts.source || "catalog",
      storyId: opts.storyId || null,
      steps: steps.map((name) => ({ name, status: "Pending" })),
      index: 0,
      progress: 0,
      status: "running",
      result: null,
      onComplete: typeof opts.onComplete === "function" ? opts.onComplete : null,
      startedAt: Date.now(),
    };
    this.minimized = false;
    this.renderModal();
    this.updateTopbar();
    this.timer = setInterval(() => this.tick(), 700);
  },

  tick() {
    const job = this.job;
    if (!job || job.status !== "running") return;

    const step = job.steps[job.index];
    if (!step) {
      this.finish(Math.random() < 0.88 ? "Passed" : "Failed");
      return;
    }

    if (step.status === "Pending") {
      step.status = "Running";
    } else if (step.status === "Running") {
      step.status = "Passed";
      job.index += 1;
    }

    job.progress = Math.min(1, (job.index + (step.status === "Running" ? 0.45 : 0)) / job.steps.length);

    if (job.index >= job.steps.length) {
      this.finish(Math.random() < 0.88 ? "Passed" : "Failed");
      return;
    }

    if (!this.minimized) {
      // Keep simple modal stable while running; refresh only when needed
      const title = document.getElementById("bot-run-title");
      if (!title || title.textContent !== "Bot Running") this.renderModal();
    }
    this.updateTopbar();
  },

  finish(result) {
    this.stopTimer();
    if (!this.job) return;
    this.job.status = "done";
    this.job.result = result;
    this.job.progress = 1;
    this.job.steps.forEach((s) => {
      if (s.status !== "Passed") s.status = "Passed";
    });
    if (this.job.onComplete) {
      try {
        this.job.onComplete(result);
      } catch (e) {}
    }
    if (!this.minimized) this.renderModal();
    this.updateTopbar();
  },

  stopTimer() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  },

  minimize() {
    if (this._minimizing) return;
    this.minimized = true;
    this.updateTopbar();

    const root = document.getElementById("bot-run-modal-root");
    const modal = root && root.querySelector(".bot-run-modal");
    const bg = document.getElementById("bot-run-bg");
    const target = document.getElementById("bot-run-status");

    if (!modal || !target || target.hidden) {
      this.removeModal();
      return;
    }

    this._minimizing = true;
    const modalRect = modal.getBoundingClientRect();
    const targetRect = target.getBoundingClientRect();
    const dx = targetRect.left + targetRect.width / 2 - (modalRect.left + modalRect.width / 2);
    const dy = targetRect.top + targetRect.height / 2 - (modalRect.top + modalRect.height / 2);
    const scale = Math.max(
      0.06,
      Math.min(targetRect.width / modalRect.width, targetRect.height / modalRect.height) * 0.9,
    );

    modal.style.setProperty("--min-x", dx + "px");
    modal.style.setProperty("--min-y", dy + "px");
    modal.style.setProperty("--min-scale", String(scale));

    // Force reflow so the transition starts from the centered state
    void modal.offsetWidth;
    if (bg) bg.classList.add("is-minimizing");
    modal.classList.add("is-minimizing");
    target.classList.add("is-awaiting");

    let finished = false;
    const finishMinimize = () => {
      if (finished) return;
      finished = true;
      modal.removeEventListener("transitionend", onTransitionEnd);
      this._minimizing = false;
      this.removeModal();
      target.classList.remove("is-awaiting");
      target.classList.add("is-catch");
      setTimeout(() => target.classList.remove("is-catch"), 450);
    };
    const onTransitionEnd = (e) => {
      if (e.target !== modal || e.propertyName !== "transform") return;
      finishMinimize();
    };
    modal.addEventListener("transitionend", onTransitionEnd);
    setTimeout(finishMinimize, 520);
  },

  closeUi() {
    // Close/dismiss UI; keep job running or finished in background
    this.minimize();
  },

  expand() {
    if (!this.job) return;
    this.minimized = false;
    this.renderModal();
    this.updateTopbar();
  },

  dismiss() {
    // Fully clear after done, or minimize if still running
    if (this.job && this.job.status === "running") {
      this.minimize();
      return;
    }
    this.stopTimer();
    this.job = null;
    this.minimized = false;
    this.removeModal();
    this.updateTopbar();
  },

  removeModal() {
    const el = document.getElementById("bot-run-modal-root");
    if (el) el.remove();
  },

  stepTone(status) {
    if (status === "Passed") return "pass";
    if (status === "Running") return "info";
    if (status === "Failed") return "fail";
    return "neutral";
  },

  renderModal() {
    const job = this.job;
    if (!job) return;
    const host = document.getElementById("root") || document.body;
    let root = document.getElementById("bot-run-modal-root");
    if (!root) {
      root = document.createElement("div");
      root.id = "bot-run-modal-root";
      host.appendChild(root);
    }

    const running = job.status === "running";

    root.innerHTML = `
      <div class="sn-modal-bg" id="bot-run-bg"></div>
      <div class="sn-modal bot-run-modal bot-run-simple" role="dialog" aria-modal="true" aria-labelledby="bot-run-title">
        <button type="button" class="sn-modal-close bot-run-x" id="bot-run-x" aria-label="Close">×</button>
        <div class="bot-run-simple-body">
          <div class="bot-run-anim ${running ? "is-spin" : job.result === "Passed" ? "is-ok" : "is-fail"}" aria-hidden="true">
            ${
              running
                ? `<span class="bot-dots"><i></i><i></i><i></i></span>`
                : job.result === "Passed"
                  ? `<span class="bot-run-check">✓</span>`
                  : `<span class="bot-run-check">!</span>`
            }
          </div>
          <h3 id="bot-run-title">${running ? "Bot Running" : job.result === "Passed" ? "Bot finished" : "Bot failed"}</h3>
          <p class="bot-run-hint">You can minimize or close this status message. The bot will keep running in the background.</p>
          <div class="bot-run-simple-actions">
            <button type="button" class="btn btn-outline" id="bot-run-min">Minimize</button>
            <button type="button" class="btn btn-outline" id="bot-run-close">${running ? "Close" : "Done"}</button>
          </div>
        </div>
      </div>`;

    document.getElementById("bot-run-min").onclick = () => this.minimize();
    document.getElementById("bot-run-close").onclick = () => this.dismiss();
    document.getElementById("bot-run-x").onclick = () => this.dismiss();
    document.getElementById("bot-run-bg").onclick = () => this.minimize();
  },

  updateTopbar() {
    const el = document.getElementById("bot-run-status");
    if (!el) return;
    const job = this.job;
    if (!job) {
      el.hidden = true;
      el.textContent = "";
      el.classList.remove("is-running", "is-done", "is-fail");
      return;
    }

    el.hidden = false;
    el.classList.toggle("is-running", job.status === "running");
    el.classList.toggle("is-done", job.status === "done" && job.result === "Passed");
    el.classList.toggle("is-fail", job.status === "done" && job.result !== "Passed");

    if (job.status === "running") {
      el.innerHTML = `<span class="bot-pulse"></span> Bot Running`;
    } else if (job.result === "Passed") {
      el.innerHTML = `<span class="bot-pulse done"></span> Bot finished · Passed`;
    } else {
      el.innerHTML = `<span class="bot-pulse fail"></span> Bot finished · Failed`;
    }
  },
};

