                <div class="region-meta"><span>${r.region}</span><strong style="color:var(--aa-orange)">${r.rate}%</strong></div>
                ${progress(r.rate / 100, "green")}
              </div>`,
              )
              .join("")}
          </div>
        </div>`
    : `
        <div class="panel">
          <div class="panel-hd"><h2>By region</h2></div>
          <div class="panel-bd">
            ${byRegion
              .map(
                (r) => `<div class="region-row">
                <div class="region-meta"><span>${r.region}</span><strong style="color:var(--aa-orange)">${r.rate}%</strong></div>
                ${progress(r.rate / 100, "green")}
              </div>`,
              )
              .join("")}
          </div>
        </div>
        <div class="panel">
          <div class="panel-hd"><h2>Test coverage</h2></div>
          <div class="panel-bd">
            ${coverageBars
              .map(
                (r) => `<div class="region-row">
                <div class="region-meta"><span>${r.name}</span><strong style="color:var(--aa-orange)">${r.rate}%</strong></div>
                ${progress(r.rate / 100, r.rate >= 85 ? "green" : "amber")}
              </div>`,
              )
              .join("")}
          </div>
        </div>`;

  root.innerHTML = `
    <div class="panel hero-panel">
      <div class="page-hd" style="align-items:flex-start">
        <div class="hero-copy">
          <h2>${hero.title}</h2>
          <p>${hero.copy}</p>
          <div class="hero-actions">
            ${hero.actions}
          </div>
        </div>
      </div>
    </div>

    ${stats}

    <div class="grid-2 xl-2-1">
      <div class="panel">
        <div class="panel-hd">
          <h2>Recent run trend</h2>
          <div class="legend">
            <span><i style="background:#ff6a3d"></i>Passed</span>
            <span><i style="background:#9f1239"></i>Failed</span>
            <span><i style="background:#f5a623"></i>In progress</span>
          </div>
        </div>
        <div class="panel-bd">
          <div class="bar-chart">
            ${batches
              .slice(0, 8)
              .reverse()
              .map((b) => {
                const h = (n) => Math.max(4, Math.round((n / maxTotal) * 160));
                return `<div class="bar-col" title="Run ${b.batch_id}">
                  <div class="bar-stack" style="height:${h(b.total_test_cases)}px">
                    <div class="bar-seg bar-seg-pass" style="height:${h(b.passed_count)}px"></div>
                    <div class="bar-seg bar-seg-fail" style="height:${h(b.failed_count)}px"></div>
                    <div class="bar-seg bar-seg-wait" style="height:${h(b.in_progress_count)}px"></div>
                  </div>
                  <div class="bar-label">${String(b.batch_id)}</div>
                </div>`;
              })
              .join("")}
          </div>
        </div>
      </div>
      <div class="panel">
        <div class="panel-hd"><h2>${isAdmin ? "Exception mix" : "Latest run summary"}</h2></div>
        <div class="panel-bd">
          ${
            isAdmin
              ? `
                <div class="region-row">
                  <div class="region-meta"><span>Business</span><strong style="color:var(--aa-orange)">${businessCount}</strong></div>
                  ${progress((APP_DATA.errors || []).length ? businessCount / (APP_DATA.errors || []).length : 0, "amber")}
                </div>
                <div class="region-row">
                  <div class="region-meta"><span>System</span><strong style="color:var(--aa-orange)">${systemCount}</strong></div>
                  ${progress((APP_DATA.errors || []).length ? systemCount / (APP_DATA.errors || []).length : 0, "green")}
                </div>
                <div class="region-row">
                  <div class="region-meta"><span>Failed cases</span><strong style="color:var(--fail)">${kpi.failed}</strong></div>
                  ${progress(kpi.batches ? Math.min(1, kpi.failed / Math.max(1, kpi.passed + kpi.failed)) : 0, "amber")}
                </div>`
              : recentMetrics.length
                ? recentMetrics
                    .map(
                      (m) => `<div class="region-row">
                      <div class="region-meta"><span>${m.process_name}</span><strong style="color:var(--aa-orange)">${m.total_count ? Math.round((m.passed_count / m.total_count) * 100) : 0}%</strong></div>
                      ${progress(m.total_count ? m.passed_count / m.total_count : 0, m.failed_count ? "amber" : "green")}
                      <div class="muted" style="font-size:12px;margin-top:4px">${m.scenario_name}</div>
                    </div>`,
                    )
                    .join("")
                : `<div class="empty">No summary yet</div>`
          }
        </div>
      </div>
    </div>

    <div class="grid-2 xl-2-1 overview-split">
      <div class="panel">
        <div class="panel-hd">
          <h2>Recent runs</h2>
          ${
            isAdmin
              ? `<a href="#exceptions" style="color:var(--aa-orange-dark);font-size:14px;font-weight:600;white-space:nowrap">Exceptions →</a>`
              : `<a href="#reports" style="color:var(--aa-orange-dark);font-size:14px;font-weight:600;white-space:nowrap">View results →</a>`
          }
        </div>
        <div class="scroll">
          <table>
            <thead>
              <tr>
                <th>Run</th>
                <th>Input file</th>
                <th>Started</th>
                <th>Status</th>
                <th class="right">Passed</th>
                <th class="right">Failed</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              ${batches
                .slice(0, 6)
                .map((b) => {
                  const tone =
                    b.overall_status === "Running"
                      ? "info"
                      : b.overall_status === "Completed"
                        ? "pass"
                        : "warn";
                  const label =
                    b.overall_status === "CompletedWithErrors"
                      ? "With errors"
                      : b.overall_status === "Running"
                        ? "In progress"
                        : b.overall_status;
                  const openHref = isAdmin ? "#exceptions" : `#run?batch=${b.batch_id}`;
                  return `<tr>
                    <td style="font-weight:600;color:var(--text)">Run ${b.batch_id}</td>
                    <td>${b.source_file_name}</td>
                    <td>${fmtTime(b.run_started_at)}</td>
                    <td>${badge(label, tone)}</td>
                    <td class="right" style="color:var(--aa-orange);font-weight:600">${b.passed_count}</td>
                    <td class="right" style="color:var(--fail);font-weight:600">${b.failed_count}</td>
                    <td><a href="${openHref}" style="color:var(--aa-orange-dark);font-weight:600;font-size:14px;white-space:nowrap">${isAdmin ? "Review" : "Open"}</a></td>
                  </tr>`;
                })
                .join("")}
            </tbody>
          </table>
        </div>
      </div>
      <div class="stack overview-side">
        ${sidePanel}
      </div>
    </div>
  `;
};

/* ----- Page: catalog ----- */
window.Pages.catalog = function () {
  const root = document.getElementById("catalog-root");
  if (!root) return;
  const { fmtTime, progress, badge } = Utils;

  let q = "";
  let region = "All";
  let story = "All";
  let process = "All";
  let selected = new Set();
  let detail = null;

  const focusStory = sessionStorage.getItem("wfta_catalog_story") || "";
  if (focusStory) {
    story = focusStory;
    sessionStorage.removeItem("wfta_catalog_story");
  }
  const shouldSelectStory = sessionStorage.getItem("wfta_catalog_select_story") === "1";
  if (shouldSelectStory) sessionStorage.removeItem("wfta_catalog_select_story");

  const regions = [...new Set(APP_DATA.catalog.map((c) => c.region))];
  const stories = [...new Set(APP_DATA.catalog.map((c) => c.story_number || c.story_id).filter(Boolean))];
  const processes = [...new Set(APP_DATA.catalog.map((c) => c.process_name))];

  function filtered() {
    return APP_DATA.catalog.filter((c) => {
      if (region !== "All" && c.region !== region) return false;
      if (story !== "All") {
        const sid = String(c.story_id || "");
        const snum = String(c.story_number || "");
        if (sid !== String(story) && snum !== String(story)) return false;
      }
      if (process !== "All" && c.process_name !== process) return false;
      if (q) {
        const hay = `${c.test_case_name} ${c.bms_worker_id} ${c.location} ${c.story_number || ""} ${c.initiator || ""}`.toLowerCase();
        if (!hay.includes(q.toLowerCase())) return false;
      }
      return true;
    });
  }

  if (shouldSelectStory && story !== "All") {
    selected = new Set(
      APP_DATA.catalog
        .filter((c) => String(c.story_id) === String(story) || String(c.story_number) === String(story))
        .filter((c) => c.enabled)
        .map((c) => String(c.staging_id))
    );
  }

  function render() {
    const prev = document.activeElement;
    const keepSearch = prev && prev.id === "f-q";
    const selStart = keepSearch ? prev.selectionStart : null;
    const selEnd = keepSearch ? prev.selectionEnd : null;
    const items = filtered();
    root.innerHTML = `
      <div class="panel">
        <div class="panel-hd">
          <h2>Test catalog</h2>
          <div class="btn-row catalog-actions">
            <span class="catalog-chip">${items.length} shown</span>
            <span class="catalog-chip catalog-chip-accent">${selected.size} selected</span>
            <button class="btn btn-outline" id="btn-all" type="button">Select ready</button>
            <button class="btn btn-primary" id="btn-run" type="button" ${selected.size ? "" : "disabled"}>RUN${selected.size ? ` ${selected.size}` : ""}</button>
          </div>
        </div>
                <div class="filters">
          <div class="field"><label>Search</label><input id="f-q" value="${q}" placeholder="Test case, worker ID, story…" /></div>
          <div class="field"><label>Region</label><select id="f-region"><option>All</option>${regions.map((r) => `<option ${r === region ? "selected" : ""}>${r}</option>`).join("")}</select></div>
          <div class="field"><label>Story</label><select id="f-story"><option value="All" ${story === "All" ? "selected" : ""}>All</option>${stories.map((r) => {
            const match = String(story) === String(r) || APP_DATA.catalog.some((c) => c.story_number === r && String(c.story_id) === String(story));
            return `<option value="${r}" ${match ? "selected" : ""}>${r}</option>`;
          }).join("")}</select></div>
          <div class="field"><label>Process</label><select id="f-proc"><option>All</option>${processes.map((r) => `<option ${r === process ? "selected" : ""}>${r}</option>`).join("")}</select></div>
        </div>
      </div>
      <div class="panel">
        <div class="scroll">
          <table>
            <thead>
              <tr>
                <th></th>
                <th>Test case</th>
                <th>Process</th>
                <th>Story</th>
                <th>Region</th>
                <th>Worker ID</th>
                <th>Salary type</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              ${items
                .map((c) => {
                  const on = selected.has(String(c.staging_id));
                  return `<tr data-id="${c.staging_id}" style="${on ? "background:var(--aa-orange-soft)" : ""}">
                    <td><input type="checkbox" data-check="${c.staging_id}" ${on ? "checked" : ""} ${c.enabled ? "" : "disabled"} /></td>
                    <td style="font-weight:600;color:var(--text)">${c.test_case_name}</td>
                    <td>${badge(c.process_name.includes("Job") ? "Job change" : "Comp change", c.process_name.includes("Job") ? "violet" : "info")}</td>
                    <td>${c.story_number || c.story_id || "—"}</td>
                    <td>${c.region} <span class="muted">· ${c.location || ""}</span></td>
                    <td>${c.bms_worker_id}</td>
                    <td>${c.salary_type}</td>
                    <td>${c.enabled ? badge("Ready", "pass") : badge("Backlog", "neutral")}</td>
                  </tr>`;
                })
                .join("")}
            </tbody>
          </table>
        </div>
      </div>
    `;

    document.getElementById("f-q").oninput = (e) => {
      q = e.target.value;
      render();
    };
    document.getElementById("f-region").onchange = (e) => {
      region = e.target.value;
      render();
    };
    document.getElementById("f-story").onchange = (e) => {
      const v = e.target.value;
      if (v === "All") {
        story = "All";
      } else {
        const hit = APP_DATA.catalog.find((c) => c.story_number === v);
        story = hit ? hit.story_id : v;
      }
      render();
    };
    document.getElementById("f-proc").onchange = (e) => {
      process = e.target.value;
      render();
    };
    document.getElementById("btn-all").onclick = () => {
      const eligible = items.filter((i) => i.enabled).map((i) => String(i.staging_id));
      const allOn = eligible.every((id) => selected.has(id));
      selected = allOn ? new Set() : new Set(eligible);
      render();
    };
    const btnRun = document.getElementById("btn-run");
    if (btnRun) {
      btnRun.onclick = () => {
        if (!selected.size) return;
        const cases = [...selected]
          .map((id) => APP_DATA.catalog.find((c) => String(c.staging_id) === String(id)))
          .filter(Boolean);
        if (!cases.length) return;
        window.BotRunner.start({
          title: "Bot Running",
          source: "catalog",
          steps: cases.map((c) => c.test_case_name),
        });
      };
    }
    root.querySelectorAll("[data-check]").forEach((el) => {
      el.onclick = (e) => e.stopPropagation();
      el.onchange = () => {
        const id = el.getAttribute("data-check");
        if (selected.has(id)) selected.delete(id);
        else selected.add(id);
        render();
      };
    });
    root.querySelectorAll("tbody tr").forEach((tr) => {
      tr.onclick = () => {
        detail = APP_DATA.catalog.find((c) => String(c.staging_id) === tr.dataset.id) || null;
        render();
      };
    });
    syncDrawer();
    Utils.enhanceSelects(root);
    if (keepSearch) {
      const el = document.getElementById("f-q");
      if (el) {
        el.focus();
        if (selStart != null && selEnd != null) {
          try { el.setSelectionRange(selStart, selEnd); } catch (e) {}
        }
      }
    }
  }

  function syncDrawer() {
    let host = document.getElementById("catalog-drawer-root");
    if (!detail) {
      if (host) host.remove();
      return;
    }
    if (!host) {
      host = document.createElement("div");
      host.id = "catalog-drawer-root";
      document.body.appendChild(host);
    }
    host.innerHTML = drawer(detail);
    const panel = host.querySelector(".drawer");
    const bg = host.querySelector("#drawer-bg");
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (panel) panel.classList.add("is-open");
        if (bg) bg.classList.add("is-open");
      });
    });
    const close = () => {
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        detail = null;
        host.remove();
        render();
      };
      if (panel) panel.classList.remove("is-open");
      if (bg) bg.classList.remove("is-open");
      if (panel) {
        panel.addEventListener("transitionend", finish, { once: true });
      }
      setTimeout(finish, 320);
    };
    const x = host.querySelector("#drawer-x");
    if (x) x.onclick = close;
    if (bg) bg.onclick = close;
  }

  function drawer(c) {
    return `
      <div class="drawer-bg" id="drawer-bg"></div>
      <aside class="drawer" role="dialog" aria-modal="true" aria-label="Test case">
        <div class="drawer-hd">
          <button type="button" class="drawer-close-x" id="drawer-x" aria-label="Close">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
          </button>
          <h3 style="margin:0;color:var(--text);font-size:18px">${c.test_case_name}</h3>
          <p class="muted" style="margin:6px 0 0;font-size:14px">${c.process_name} · ${c.scenario_name}</p>
        </div>
        <div class="drawer-bd">
          <div class="grid-2" style="margin-bottom:14px">
            <div class="panel panel-bd"><div class="muted" style="font-size:11px;text-transform:uppercase">Initiator</div><div>${c.initiator}</div></div>
            <div class="panel panel-bd"><div class="muted" style="font-size:11px;text-transform:uppercase">Worker ID</div><div>${c.bms_worker_id}</div></div>
            <div class="panel panel-bd"><div class="muted" style="font-size:11px;text-transform:uppercase">Region</div><div>${c.region} · ${c.country}</div></div>
            <div class="panel panel-bd"><div class="muted" style="font-size:11px;text-transform:uppercase">Effective date</div><div>${c.effective_date}</div></div>
            <div class="panel panel-bd"><div class="muted" style="font-size:11px;text-transform:uppercase">Salary type</div><div>${c.salary_type}</div></div>
            <div class="panel panel-bd"><div class="muted" style="font-size:11px;text-transform:uppercase">Last run</div><div>${fmtTime(c.last_run_at)}</div></div>
          </div>
          <div class="panel panel-bd" style="border-color:#f7c9d0;background:#fff0f2;margin-bottom:14px">
            <div style="color:var(--fail);font-size:11px;font-weight:650;text-transform:uppercase;margin-bottom:6px">Expected hard-stop message</div>
            <div style="font-size:14px;color:var(--text)">“${c.expected_result}”</div>
          </div>
          <div class="muted" style="font-size:11px;text-transform:uppercase;margin-bottom:8px">Test steps</div>
          <ol style="margin:0;padding-left:18px;color:var(--text-2);font-size:14px;line-height:1.65">
            ${(Array.isArray(c.test_steps) ? c.test_steps : String(c.test_steps).split(" | ")).map((s) => `<li style="margin-bottom:6px">${s}</li>`).join("")}
          </ol>
        </div>
      </aside>`;
  }

  render();
};

