  let viewMode = sessionStorage.getItem("wfta_sn_view") || "card";
  let syncing = false;

  function stateTone(state) {
    if (state === "Complete") return "pass";
    if (state === "Work in Progress") return "info";
    if (state === "Ready") return "violet";
    if (state === "Cancelled") return "fail";
    return "neutral";
  }

  function botTone(status) {
    if (status === "Passed") return "pass";
    if (status === "Failed") return "fail";
    if (status === "Running") return "info";
    if (status === "Queued") return "warn";
    return "neutral";
  }

  function shortState(state) {
    if (state === "Work in Progress") return "WIP";
    return state;
  }

  function timeAgo(iso) {
    if (!iso) return "Just now";
    const t = new Date(iso).getTime();
    if (Number.isNaN(t)) return "Just now";
    const diff = Math.max(0, Date.now() - t);
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return "Just now";
    if (mins < 60) return mins + "m ago";
    const hours = Math.floor(mins / 60);
    if (hours < 24) return hours + "h ago";
    const days = Math.floor(hours / 24);
    if (days < 30) return days + "d ago";
    return Math.floor(days / 30) + "mo ago";
  }

  function instanceHost() {
    const raw = snow.instance || "ServiceNow";
    return String(raw).replace(/^https?:\/\//i, "").replace(/\/$/, "");
  }

  function openStory() {
    return stories.find((s) => s.sys_id === openId) || null;
  }

  function clearModalNode() {
    const existing = document.getElementById("sn-modal-root");
    if (existing) existing.remove();
  }

  function runBot(story) {
    if (!story || story.state === "Cancelled") return;
    story.bot_status = "Running";
    story.updated_at = new Date().toISOString();
    openId = null;
    message = "";
    clearModalNode();
    render();
    window.BotRunner.start({
      title: "Bot Running",
      source: "story",
      storyId: story.sys_id,
      steps: story.steps && story.steps.length ? story.steps : APP_DATA.stepCatalog.slice(0, 8),
      onComplete(result) {
        const s = (APP_DATA.snow && APP_DATA.snow.stories || []).find((x) => x.sys_id === story.sys_id);
        if (!s) return;
        s.bot_status = result === "Passed" ? "Passed" : "Failed";
        if (s.state === "Ready" || s.state === "Draft") s.state = "Work in Progress";
        if (s.bot_status === "Passed") s.state = "Complete";
        s.updated_at = new Date().toISOString();
      },
    });
  }

  function syncNow() {
    if (syncing) return;
    syncing = true;
    render();
    setTimeout(() => {
      snow.lastSyncedAt = new Date().toISOString();
      stories.forEach((s, i) => {
        if (i % 2 === 0) s.updated_at = new Date(Date.now() - (i + 1) * 15 * 60000).toISOString();
      });
      syncing = false;
      render();
    }, 900);
  }

  let chatMessages = [];
  let stepsGenerated = false;
  let casesGenerated = false;
  let generatedSteps = [];
  let generatedCases = [];
  let stepsModalOpen = false;
  let openCase = null;

  function replyFor(prompt) {
    const p = String(prompt || "").toLowerCase();
    if (p.includes("catalog") || p.includes("test case")) {
      return "I can draft a test catalog for this story — scenarios, worker IDs, regions, and expected hard-stops. Use Generate Test Cases to fill the panel on the left.";
    }
    if (p.includes("step")) {
      return "I can generate plain-language test steps from this story. Use Generate Steps, then open Steps to review them.";
    }
    if (p.includes("map") || p.includes("scenario")) {
      return "I can map this story to Workday hard-stop scenarios. Which process should I prioritize?";
    }
    if (p.includes("bot") || p.includes("instruction")) {
      return "I can draft bot run instructions: login, proxy as initiator, open the business process, enter data, and capture the expected stop message.";
    }
    return "Got it. Ask me to generate test steps, create a test catalog, map Workday scenarios, or draft bot instructions for this story.";
  }

  function pushChat(role, text) {
    chatMessages.push({ role, text });
  }

  function resetStoryGen() {
    stepsGenerated = false;
    casesGenerated = false;
    generatedSteps = [];
    generatedCases = [];
    stepsModalOpen = false;
    stepsRegenCount = 0;
    openCase = null;
    const host = document.getElementById("story-case-drawer-root");
    if (host) host.remove();
    const modal = document.getElementById("story-steps-modal-root");
    if (modal) modal.remove();
  }

  let stepsRegenCount = 0;
  function buildGeneratedSteps(story) {
    stepsRegenCount += 1;
    const base = (story.steps && story.steps.length) ? story.steps.slice() : [
      "Open Workday and verify the correct tenant",
      "Proxy as the assigned initiator",
      "Locate the worker and open the business process",
      "Enter scenario data and submit",
      "Confirm the expected hard-stop message appears",
    ];
    const extras = [
      "Capture evidence screenshot of the hard-stop dialog",
      "Validate audit log entry for the blocked transaction",
      "Confirm initiator receives the expected notification",
    ];
    const out = base.map((s) => (typeof s === "string" ? s : String(s)));
    const extra = extras[(stepsRegenCount - 1) % extras.length];
    if (!out.includes(extra)) out.push(extra);
    if (stepsRegenCount > 1) {
      out.unshift(`Regenerated pass ${stepsRegenCount}: refine navigation and validation checks`);
    }
    return out;
  }

  function buildGeneratedCases(story) {
    const regions = [
      { region: "Americas", country: "USA", location: "New Brunswick - NJ" },
      { region: "EMEA", country: "United Kingdom", location: "Uxbridge" },
      { region: "APAC", country: "India", location: "Hyderabad" },
      { region: "Americas", country: "USA", location: "Cambridge Crossing - MA" },
    ];
    const names = [
      "Hard Stop Validation",
      "Salary Below Minimum",
      "Location Transfer Check",
      "Compensation Change Guard",
    ];
    const workers = ["00351783", "00544802", "00528485", "00494212"];
    const baseId = 8000 + Math.floor(Math.random() * 1000);
    return names.map((name, i) => {
      const site = regions[i % regions.length];
      return {
        id: `${story.sys_id}-tc-${i + 1}`,
        staging_id: baseId + i,
        batch_id: null,
        story_id: story.sys_id,
        story_number: story.number,
        test_case_name: `TC-${String(i + 1).padStart(2, "0")} ${name}`,
        process_name: i % 2 ? "Propose Job Change" : "Request Compensation Change",
        scenario_name: name,
        initiator: story.assigned_to || "HRS Initiator",
        region: site.region,
        country: site.country,
        location: site.location,
        bms_worker_id: workers[i % workers.length],
        effective_date: "2026-09-01",
        salary_type: i % 2 ? "Full time / Hourly" : "Full time / Salary",
        expected_result: "The proposed compensation is below the minimum for the selected pay grade.",
        test_steps: generatedSteps.length ? generatedSteps.slice(0, 8) : (story.steps || []).slice(0, 8),
        status: "Ready",
        enabled: 1,
        pass_rate: 80 + i,
        last_run_at: null,
        workday_instance: "Sandbox Preview",
      };
    });
  }

  function casesPanelHtml(story) {
    if (!casesGenerated || !generatedCases.length) {
      return `<div class="story-cases-empty muted">No test cases yet. Generate Test Cases to populate this list.</div>`;
