              <th>Region</th>
              <th>Worker ID</th>
              <th>Salary type</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            ${generatedCases
              .map((c) => {
                return `<tr class="story-case-row" data-case-id="${c.id || c.staging_id}">
                  <td><input type="checkbox" checked disabled /></td>
                  <td style="font-weight:600;color:var(--text)">${c.test_case_name}</td>
