  function stepsModalHtml() {
    const lines = (generatedSteps.length ? generatedSteps : [])
      .map((s) => `<p class="story-step-line">${s}</p>`)
      .join("") || `<p class="muted">No generated steps yet.</p>`;
    return `
      <div class="story-modal-bg" id="story-steps-bg"></div>
