  function syncCaseDrawer() {
    let host = document.getElementById("story-case-drawer-root");
    if (!openCase) {
      if (host) host.remove();
      return;
    }
    if (!host) {
      host = document.createElement("div");
      host.id = "story-case-drawer-root";
      document.body.appendChild(host);
    }
    host.innerHTML = caseDrawerHtml(openCase);
    const panel = host.querySelector(".drawer");
    const bg = host.querySelector("#story-case-bg");
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (panel) panel.classList.add("is-open");
        if (bg) bg.classList.add("is-open");
      });
    });
    const close = () => {
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        openCase = null;
        host.remove();
      };
      if (panel) panel.classList.remove("is-open");
      if (bg) bg.classList.remove("is-open");
      if (panel) panel.addEventListener("transitionend", finish, { once: true });
      setTimeout(finish, 320);
    };
    const x = host.querySelector("#story-case-x");
    if (x) x.onclick = close;
    if (bg) bg.onclick = close;
  }

