              <h3 class="sn-card-title">${s.short_description}</h3>
              <div class="sn-card-meta">
                <span class="sn-chip sn-chip-sm ${stateTone(s.state)}">${shortState(s.state)}</span>
                <span class="sn-chip sn-chip-sm ${botTone(s.bot_status)}">${s.bot_status}</span>
              </div>
              <div class="sn-card-foot">
                <span class="sn-assignee">${s.assigned_to || ""}</span>
                <button type="button" class="sn-chip sn-chip-sm sn-process-btn" data-open="${s.sys_id}">Process</button>
              </div>
            </article>`
          )
          .join("")}
      </div>`;
  }

  function render() {
    sessionStorage.setItem("wfta_sn_view", viewMode);
    const story = openStory();
    clearModalNode();

    if (story) {
      if (!chatMessages.length) {
        pushChat(
          "assistant",
          "Hi. Ask me to generate steps, build a test catalog, map scenarios, or draft bot instructions."
        );
      }
      root.innerHTML = detailHtml(story);
      bindStoryDetail(story);
      return;
    }

    root.innerHTML = `
      <div class="panel run-top-panel">
        <div class="run-top-actions">
          <div class="sn-toolbar">
            <div class="sn-toolbar-left">
              <div class="sn-instance sn-instance-row" title="${snow.instance || ""}">
                <div class="sn-instance-copy">
                  <span class="sn-instance-label">ServiceNow</span>
                  <strong>${instanceHost()}</strong>
                  <span class="sn-instance-meta">${timeAgo(snow.lastSyncedAt)}</span>
                </div>
              </div>
            </div>
            <div class="sn-toolbar-right">
              <div class="sn-view-switch" role="group" aria-label="View mode">
                <button type="button" class="sn-view-btn ${viewMode === "list" ? "on" : ""}" data-view="list" title="List view">${I.list}</button>
                <button type="button" class="sn-view-btn ${viewMode === "card" ? "on" : ""}" data-view="card" title="Card view">${I.grid}</button>
              </div>
              <button type="button" class="btn btn-outline sn-sync-btn" id="sn-sync" ${syncing ? "disabled" : ""} title="Sync stories">
                <span class="sn-ico ${syncing ? "spin" : ""}">${I.sync}</span>
                ${syncing ? "Syncing" : "Sync"}
              </button>
            </div>
          </div>
        </div>
      </div>
      ${viewMode === "card" ? cardsHtml() : listHtml()}
    `;

    root.querySelectorAll("[data-view]").forEach((btn) => {
      btn.onclick = () => {
        viewMode = btn.getAttribute("data-view");
        render();
      };
    });

    const syncBtn = document.getElementById("sn-sync");
    if (syncBtn) syncBtn.onclick = syncNow;

    root.querySelectorAll("[data-open]").forEach((el) => {
      el.onclick = (e) => {
        e.stopPropagation();
        openId = el.getAttribute("data-open");
        message = "";
        chatMessages = [];
        resetStoryGen();
        render();
      };
    });
  }

  render();
};

/* ----- Page: reports ----- */
window.Pages.reports = function () {
  const root = document.getElementById("reports-root");
  if (!root) return;
  const { fmtDuration, fmtTime, badge, progress, qs } = Utils;

  let batchId = qs("batch") || "All";
  let result = "All";
  let region = "All";
  let q = "";
  let open = null;

  function rows() {
    return APP_DATA.executions
      .map((e) => {
        const s = APP_DATA.staging.find((x) => x.staging_id === e.staging_id);
        const b = APP_DATA.batches.find((x) => x.batch_id === s?.batch_id);
        return { ...e, staging: s, batch: b };
      })
      .filter((r) => r.staging)
      .filter((r) => {
        if (batchId !== "All" && String(r.staging.batch_id) !== String(batchId)) return false;
        if (result !== "All" && r.status !== result) return false;
        if (region !== "All" && r.staging.region !== region) return false;
        if (q) {
          const hay = `${r.staging.test_case_name} ${r.staging.bms_worker_id} ${r.bot_runner_id}`.toLowerCase();
          if (!hay.includes(q.toLowerCase())) return false;
        }
        return true;
      });
  }

  function render() {
    const prev = document.activeElement;
    const keepSearch = prev && prev.id === "r-q";
    const selStart = keepSearch ? prev.selectionStart : null;
    const selEnd = keepSearch ? prev.selectionEnd : null;
    const items = rows();
    const passed = items.filter((i) => i.status === "Passed").length;
    const failed = items.filter((i) => i.status === "Failed").length;
    const running = items.filter((i) => i.status === "Running").length;
    const rate = items.length - running ? Math.round((passed / (items.length - running || 1)) * 100) : 0;

    root.innerHTML = `
      <div class="panel">
        <div class="panel-hd">
          <h2>Test results</h2>
          <div class="pass-rate-inline" title="Pass rate for current filters">
            <span class="muted">Pass rate</span>
            ${progress(rate / 100, rate >= 90 ? "green" : "amber")}
            <strong>${rate}%</strong>
          </div>
        </div>
        <div class="filters">
          <div class="field"><label>Search</label><input id="r-q" value="${q}" placeholder="Test case, worker ID…" /></div>
          <div class="field"><label>Run</label><select id="r-batch"><option>All</option>${APP_DATA.batches.map((b) => `<option ${String(b.batch_id) === String(batchId) ? "selected" : ""}>Run ${b.batch_id}</option>`).join("")}</select></div>
          <div class="field"><label>Result</label><select id="r-res"><option>All</option>${["Passed", "Failed", "Running"].map((x) => `<option ${x === result ? "selected" : ""}>${x}</option>`).join("")}</select></div>
          <div class="field"><label>Region</label><select id="r-reg"><option>All</option>${["Americas", "EMEA", "APAC"].map((x) => `<option ${x === region ? "selected" : ""}>${x}</option>`).join("")}</select></div>
        </div>
      </div>
      <div class="grid-4">
        <div class="panel stat"><p class="label">Results</p><p class="value">${items.length}</p></div>
        <div class="panel stat"><p class="label">Passed</p><p class="value" style="color:var(--pass)">${passed}</p></div>
        <div class="panel stat"><p class="label">Failed</p><p class="value" style="color:var(--fail)">${failed}</p></div>
        <div class="panel stat"><p class="label">Running</p><p class="value" style="color:var(--info)">${running}</p></div>
      </div>
      <div class="panel">
        <div class="scroll">
          <table>
            <thead>
              <tr>
                <th>Run</th>
                <th>Input file</th>
                <th>Test case</th>
                <th>Runner</th>
                <th>Started</th>
                <th>Status</th>
                <th class="right">Evidence</th>
              </tr>
            </thead>
            <tbody>
              ${items
                .map((r) => {
                  const tone = r.status === "Passed" ? "pass" : r.status === "Failed" ? "fail" : "info";
                  const inputFile = r.batch?.source_file_name || "Input workbook";
                  const canDl = r.status === "Passed" || r.status === "Failed";
                  const dlBtn = canDl
                    ? `<button type="button" class="btn btn-outline res-dl-btn" data-dl="${r.execution_id}" title="Download evidence">
                        <span class="sn-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg></span> Download
                      </button>`
                    : `<button type="button" class="btn btn-outline res-dl-btn" disabled title="Available after run completes">
                        <span class="sn-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg></span> Download
                      </button>`;
                  return `<tr data-id="${r.execution_id}" style="cursor:pointer">
                    <td style="font-weight:600;color:var(--text)">Run ${r.staging.batch_id}</td>
                    <td title="${inputFile}">${inputFile}</td>
                    <td>${r.staging.test_case_name}</td>
                    <td>${r.bot_runner_id}</td>
                    <td>${fmtTime(r.started_at)}</td>
                    <td>${badge(r.status, tone)}</td>
                    <td class="right" onclick="event.stopPropagation()">${dlBtn}</td>
                  </tr>
                  ${
                    open === r.execution_id
                      ? `<tr><td colspan="7" style="background:#fff8f4">
                      <div style="padding:10px 4px" class="grid-2">
                        <div>
                          <div class="muted" style="font-size:11px;text-transform:uppercase;margin-bottom:6px">Input file</div>
                          <div style="font-size:14px;color:var(--text);font-weight:600">${inputFile}</div>
                          <div class="muted" style="margin-top:10px;font-size:11px;text-transform:uppercase;margin-bottom:6px">Details</div>
                          <div style="font-size:14px;color:var(--text-2)">${r.staging.process_name} · ${r.staging.initiator} · ${r.staging.region} / ${r.staging.location}</div>
                          <div class="muted" style="margin-top:6px;font-size:12px">Worker ${r.staging.bms_worker_id} · attempt ${r.staging.attempt_number} · retries ${r.staging.retry_count}</div>
                        </div>
                        <div>
                          <div class="muted" style="font-size:11px;text-transform:uppercase;margin-bottom:6px">Last update</div>
                          <div style="font-size:14px">${fmtTime(r.last_heartbeat_at)}</div>
                          <div class="muted" style="margin-top:6px;font-size:13px">${r.screenshots} screenshots · ${r.staging.workday_instance}</div>
                        </div>
                      </div>
                    </td></tr>`
                      : ""
                  }`;
                })
                .join("")}
            </tbody>
          </table>
        </div>
      </div>`;

    document.getElementById("r-batch").onchange = (e) => {
      const v = e.target.value;
      batchId = v === "All" ? "All" : v.replace("Run ", "");
      render();
    };
    document.getElementById("r-res").onchange = (e) => {
      result = e.target.value;
      render();
    };
    document.getElementById("r-reg").onchange = (e) => {
      region = e.target.value;
      render();
    };
    document.getElementById("r-q").oninput = (e) => {
      q = e.target.value;
      render();
    };
    root.querySelectorAll("tbody tr[data-id]").forEach((tr) => {
      tr.onclick = () => {
        const id = Number(tr.dataset.id);
        open = open === id ? null : id;
        render();
      };
    });

    root.querySelectorAll("[data-dl]").forEach((btn) => {
      btn.onclick = (e) => {
        e.stopPropagation();
        const id = btn.getAttribute("data-dl");
        const row = APP_DATA.executions.find((x) => String(x.execution_id) === String(id));
        const st = APP_DATA.staging.find((x) => x.staging_id === row?.staging_id);
        const name = (st?.test_case_name || "evidence").replace(/[^a-zA-Z0-9_-]+/g, "_");
        const blob = new Blob(
          [`Evidence pack for ${st?.test_case_name || id}\nStatus: ${row?.status}\nRunner: ${row?.bot_runner_id}\nScreenshots: ${row?.screenshots || 0}\n`],
          { type: "text/plain" }
        );
        const a = document.createElement("a");
        a.href = URL.createObjectURL(blob);
        a.download = `${name}_evidence.txt`;
        a.click();
        URL.revokeObjectURL(a.href);
      };
    });
    Utils.enhanceSelects(root);
    if (keepSearch) {
      const el = document.getElementById("r-q");
      if (el) {
        el.focus();
        if (selStart != null && selEnd != null) {
          try { el.setSelectionRange(selStart, selEnd); } catch (e) {}
        }
      }
    }
  }

  render();
};

/* ----- Page: evidence ----- */
window.Pages.evidence = function () {
  const root = document.getElementById("evidence-root");
  if (!root) return;
  const { badge, fmtDuration, fmtTime } = Utils;

  const ROOT_PATH = "/sites/BMS-RPA/Shared Documents/WorkDayAgent/Output";

  const FOLDER_SVG =
    '<svg class="folder-ico" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M3.5 7.2A2.2 2.2 0 0 1 5.7 5h3.2l1.4 1.7h8a2.2 2.2 0 0 1 2.2 2.2v8.4A2.2 2.2 0 0 1 18.3 20H5.7A2.2 2.2 0 0 1 3.5 17.8V7.2z"/></svg>';

  function folderDate(iso) {
    const d = new Date(iso);
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return `${mm}-${dd}-${d.getFullYear()}`;
  }

  function caseId(name) {
    return String(name || "TC").split(" ")[0];
  }

  function slug(name) {
    return String(name)
      .replace(/[^a-zA-Z0-9]+/g, "_")
      .replace(/^_|_$/g, "");
  }

  function shotsFor(exec) {
    return APP_DATA.steps
      .filter((s) => s.execution_id === exec?.execution_id)
      .filter((s) => s.step_status === "Passed" || s.step_status === "Failed" || s.step_status === "Running")
      .map((s) => ({
        step: s,
        file: `${String(s.step_sequence).padStart(2, "0")}_${slug(s.step_name)}.png`,
        status: s.step_status,
      }));
  }

  const folders = APP_DATA.batches.map((b) => {
    const items = APP_DATA.staging
      .filter((s) => s.batch_id === b.batch_id)
      .map((s) => {
        const exec = APP_DATA.executions.find((e) => e.staging_id === s.staging_id);
        const shots = shotsFor(exec);
        return { staging: s, exec, shots, id: caseId(s.test_case_name) };
      });
    const date = folderDate(b.run_started_at);
    return {
      batch: b,
      date,
      folder: date,
      items,
      screenshots: items.reduce((n, it) => n + it.shots.length, 0),
    };
  });

  let activeDate = folders[0]?.date || null;
  let activeCase = null;
  let openShot = null;

  function shotFrame(shot, large) {
    const err = shot.step.error_message;
    const tone = shot.status === "Failed" ? "fail" : shot.status === "Running" ? "run" : "ok";
    return `<div class="shot-frame ${tone}${large ? " lg" : ""}">
      <div class="shot-chrome"><span class="shot-dots"></span><span>Workday · Sandbox Preview</span></div>
      <div class="shot-canvas">
        <div class="shot-title">${shot.step.step_name}</div>
        <div class="shot-rows"><i></i><i></i><i></i></div>
        ${err ? `<div class="shot-alert">${err}</div>` : ""}
        ${shot.status === "Running" ? `<div class="shot-live">Capturing…</div>` : ""}
      </div>
    </div>`;
  }

  function render() {
    const current = folders.find((f) => f.date === activeDate) || folders[0];
    const selected = current?.items.find((it) => it.staging.staging_id === activeCase) || null;
    const path = selected
      ? `${ROOT_PATH}/${current.folder}/${selected.id}`
      : current
        ? `${ROOT_PATH}/${current.folder}`
        : ROOT_PATH;
    const totalFiles = folders.reduce((n, f) => n + f.screenshots, 0);

    root.innerHTML = `
      <div class="page-hd">
        <div>
          <h2>Evidence</h2>
          <p class="mono muted" style="margin-top:6px">${ROOT_PATH}</p>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          ${badge(folders.length + " run folders", "info")}
          ${badge(totalFiles + " screenshots", "violet")}
        </div>
      </div>
      <div class="grid-2 xl-1-2">
        <div class="panel">
          <div class="panel-hd"><h2>Run folders</h2></div>
          <div class="panel-bd ev-folder-list">
            ${folders
              .map(
                (f) => `<button type="button" class="folder-btn ${current?.date === f.date ? "on" : ""}" data-date="${f.date}">
                  ${FOLDER_SVG}
                  <span>
                    <div class="mono" style="font-size:13px;font-weight:650">${f.folder}</div>
                    <div class="muted" style="font-size:12px">Run ${f.batch.batch_id} · ${f.items.length} cases · ${f.screenshots} files</div>
                  </span>
                </button>`,
              )
              .join("")}
          </div>
        </div>
        <div class="stack">
          <div class="panel">
            <div class="panel-hd">
              <div>
                <h2>${selected ? selected.id : current ? current.folder : "Select a folder"}</h2>
                <div class="crumb">
                  <button type="button" data-crumb="root">Output</button>
                  ${current ? `<span>/</span><button type="button" data-crumb="run">${current.folder}</button>` : ""}
                  ${selected ? `<span>/</span><span>${selected.id}</span>` : ""}
                </div>
              </div>
              ${
                selected
                  ? `<button type="button" class="btn btn-outline" id="ev-back" style="height:36px;padding:0 12px;font-size:13px">Back to cases</button>`
                  : ""
              }
            </div>
            ${
              selected
                ? `<div class="panel-bd">
                    <div class="muted" style="font-size:12px;text-transform:uppercase;letter-spacing:.04em;margin-bottom:8px">SharePoint path</div>
                    <div class="mono" style="color:var(--aa-orange-dark);font-size:13px;word-break:break-all">${path}</div>
                    <p style="margin:10px 0 16px;color:var(--text-3);font-size:14px">${selected.staging.test_case_name} · ${selected.staging.initiator} · ${selected.staging.region}</p>
                    ${
                      selected.shots.length
                        ? `<div class="shot-grid">
                            ${selected.shots
                              .map(
                                (shot, i) => `<button type="button" class="shot ${openShot === i ? "on" : ""}" data-shot="${i}">
                                  ${shotFrame(shot, false)}
                                  <div class="shot-meta">
                                    <strong>${shot.file}</strong>
                                    <span>${badge(shot.status, shot.status === "Passed" ? "pass" : shot.status === "Failed" ? "fail" : "info")} ${fmtTime(shot.step.step_end_time || shot.step.step_start_time)}</span>
                                  </div>
                                </button>`,
                              )
                              .join("")}
                          </div>`
                        : `<div class="empty">Screenshots are still being captured for this test case.</div>`
                    }
                  </div>`
                : `<div class="panel-bd folder-grid">
                    ${(current?.items || [])
                      .map(
                        (it) => `<button type="button" class="case-folder" data-sid="${it.staging.staging_id}">
                          <span class="folder-glyph"></span>
                          <div class="case-folder-hd">
                            <span class="mono" style="font-weight:650">${it.id}</span>
                            ${badge(it.staging.status, it.staging.status === "Passed" ? "pass" : it.staging.status === "Failed" ? "fail" : "info")}
                          </div>
                          <div style="font-size:13px;color:var(--text-2)">${it.staging.test_case_name.replace(/^[^\s]+\s/, "")}</div>
                          <div class="muted" style="font-size:12px;margin-top:6px">${it.shots.length} screenshots · ${fmtDuration(it.exec?.duration_sec)}</div>
                        </button>`,
                      )
                      .join("") || `<div class="empty">Select a run folder</div>`}
                  </div>`
            }
          </div>
        </div>
      </div>
      ${
        selected && openShot != null && selected.shots[openShot]
          ? `<div class="shot-lightbox" id="shot-lightbox">
              <div class="shot-lightbox-card">
                <div class="panel-hd">
                  <div>
                    <h2>${selected.shots[openShot].file}</h2>
                    <div class="muted" style="font-size:12px;margin-top:4px">${path}/${selected.shots[openShot].file}</div>
                  </div>
                  <button type="button" class="btn btn-outline" id="shot-close" style="height:36px;padding:0 12px;font-size:13px">Close</button>
                </div>
                <div class="panel-bd">${shotFrame(selected.shots[openShot], true)}</div>
              </div>
            </div>`
          : ""
      }
    `;

    root.querySelectorAll("[data-date]").forEach((btn) => {
      btn.onclick = () => {
        activeDate = btn.dataset.date;
        activeCase = null;
        openShot = null;
        render();
      };
    });
    root.querySelectorAll("[data-sid]").forEach((btn) => {
      btn.onclick = () => {
        activeCase = Number(btn.dataset.sid);
        openShot = null;
        render();
      };
    });
    root.querySelectorAll("[data-shot]").forEach((btn) => {
      btn.onclick = () => {
        openShot = Number(btn.dataset.shot);
        render();
      };
    });
    const back = document.getElementById("ev-back");
    if (back)
      back.onclick = () => {
        activeCase = null;
        openShot = null;
        render();
      };
    root.querySelectorAll("[data-crumb]").forEach((btn) => {
      btn.onclick = () => {
        if (btn.dataset.crumb === "root" || btn.dataset.crumb === "run") {
          activeCase = null;
          openShot = null;
          render();
        }
      };
    });
    const close = document.getElementById("shot-close");
    if (close)
      close.onclick = () => {
        openShot = null;
        render();
      };
    const box = document.getElementById("shot-lightbox");
    if (box)
      box.onclick = (e) => {
        if (e.target === box) {
          openShot = null;
          render();
        }
      };
  }

  render();
};

/* ----- Page: exceptions ----- */
window.Pages.exceptions = function () {
  const root = document.getElementById("exceptions-root");
  if (!root) return;
  const { badge, fmtTime } = Utils;
  let type = "All";

  function render() {
    const errors = APP_DATA.errors.filter((e) => type === "All" || e.exception_type === type);
    root.innerHTML = `
      <div class="panel">
        <div class="panel-hd"><h2>Exception handling guide</h2></div>
        <div class="scroll">
          <table>
            <thead><tr><th>Ref</th><th>Type</th><th>Scenario</th><th>Action</th><th>Notify</th></tr></thead>
            <tbody>
              ${APP_DATA.exceptionMatrix
                .map(
                  (e) => `<tr>
                  <td style="font-weight:600;color:var(--text)">${e.ref}</td>
                  <td>${badge(e.type, e.type === "Business" ? "violet" : "warn")}</td>
                  <td>${e.scenario}</td>
                  <td class="muted">${e.action}</td>
                  <td>${badge(e.notify, "neutral")}</td>
                </tr>`,
                )
                .join("")}
            </tbody>
          </table>
        </div>
      </div>
      <div class="panel">
        <div class="panel-hd">
          <h2>Exceptions</h2>
          <div class="field" style="min-width:160px;margin:0">
            <select id="etype"><option>All</option><option>Business</option><option>System</option></select>
          </div>
        </div>
        <div class="scroll">
          <table>
            <thead>
              <tr>
                <th>Type</th>
                <th>Code</th>
                <th>Message</th>
                <th>When</th>
              </tr>
            </thead>
            <tbody>
              ${errors
                .map((e) => {
                  const staging = APP_DATA.staging.find((s) => s.staging_id === e.staging_id);
                  return `<tr>
                    <td>${badge(e.exception_type, e.exception_type === "System" ? "warn" : "fail")}</td>
                    <td style="font-weight:600">${e.error_code}</td>
                    <td>
                      <div>${e.error_message}</div>
                      <div class="muted" style="font-size:12px;margin-top:4px">${staging?.test_case_name || ""}</div>
                    </td>
                    <td>${fmtTime(e.occurred_at)}</td>
                  </tr>`;
                })
                .join("")}
            </tbody>
          </table>
        </div>
      </div>
    `;
    const sel = document.getElementById("etype");
    sel.value = type;
    sel.onchange = (e) => {
      type = e.target.value;
      render();
    };
    Utils.enhanceSelects(root);
  }

  render();
};

/* ----- Page: settings ----- */
window.Pages.settings = function () {
  const root = document.getElementById("settings-root");
  if (!root) return;
  const { badge } = Utils;

  root.innerHTML = `
