/* ----- Page: users (admin) ----- */
window.Pages.users = function () {
  const root = document.getElementById("users-root");
  if (!root) return;
  if (!Auth.isAdmin()) {
    root.innerHTML = `<div class="panel panel-bd"><p>Admin access required.</p></div>`;
    return;
  }

  if (!window.APP_USERS) {
    window.APP_USERS = [
      { id: "u1", name: "B. Deep", user: "bdeep", role: "User", status: "Active" },
      { id: "u2", name: "Asha Patel", user: "apatel", role: "User", status: "Active" },
      { id: "u3", name: "Marcus Chen", user: "mchen", role: "User", status: "Active" },
      { id: "u4", name: "Admin", user: "admin", role: "Admin", status: "Active" },
    ];
  }

  let showCreate = false;

  function render() {
    const users = window.APP_USERS;
    root.innerHTML = `
      <div class="panel">
        <div class="panel-hd">
          <h2>Users</h2>
          <button type="button" class="btn btn-primary" id="btn-create-user">Create user</button>
        </div>
        ${
          showCreate
            ? `<div class="panel-bd user-create-box">
                <div class="filters" style="padding:0">
                  <div class="field"><label>Name</label><input id="nu-name" placeholder="Full name" /></div>
                  <div class="field"><label>Username</label><input id="nu-user" placeholder="username" /></div>
