/* =========================================================
   ROUTER — in-widget SPA (no real page loads / parent nav)
   ========================================================= */
window.Pages = window.Pages || {};
window.AUTH_KEY = "wfta_signed_in";
window.ROLE_KEY = "wfta_role";
window.USER_KEY = "wfta_user";

const PAGE_TITLES = {
  "overview": "Overview",
  "catalog": "Test Catalog",
  "run": "Run Tests",
  "reports": "Results",
  "evidence": "Evidence",
  "exceptions": "Exceptions",
  "settings": "Settings",
  "users": "Users"
};
const PAGE_IDS = ["overview","catalog","run","reports","evidence","exceptions","settings","users"];
const ADMIN_ONLY_PAGES = ["settings", "users", "exceptions"];
const USER_ONLY_PAGES = ["catalog", "run", "reports"];

window.Auth = {
  isSignedIn() {
    return sessionStorage.getItem(window.AUTH_KEY) === "1";
  },
  isAdmin() {
    return sessionStorage.getItem(window.ROLE_KEY) === "admin";
  },
  username() {
    return sessionStorage.getItem(window.USER_KEY) || "user";
  },
  signIn(username) {
    const raw = String(username || "").trim();
    const isAdmin = raw.toLowerCase() === "admin";
    sessionStorage.setItem(window.AUTH_KEY, "1");
    sessionStorage.setItem(window.ROLE_KEY, isAdmin ? "admin" : "user");
    sessionStorage.setItem(window.USER_KEY, raw || "user");
  },
  signOut() {
    sessionStorage.removeItem(window.AUTH_KEY);
    sessionStorage.removeItem(window.ROLE_KEY);
    sessionStorage.removeItem(window.USER_KEY);
  },
  canAccess(page) {
    if (page === "evidence") return false;
    if (ADMIN_ONLY_PAGES.includes(page)) return this.isAdmin();
    if (USER_ONLY_PAGES.includes(page)) return !this.isAdmin();
    return true;
  },
  homePage() {
    return "overview";
  },
};

window.AppRouter = {
  page: "login",
  query: "",

  getQuery(name) {
    return new URLSearchParams(this.query || "").get(name);
  },

  parseHash() {
    const raw = (location.hash || "").replace(/^#/, "");
    if (!raw) return null;
    const [pagePart, query = ""] = raw.split("?");
    let page = (pagePart || "").replace(/\.html$/, "");
    if (page === "index" || page === "") page = Auth.isSignedIn() ? Auth.homePage() : "overview";
    if (page === "login") return { page: "login", query: "" };
    if (!PAGE_IDS.includes(page)) page = Auth.isSignedIn() ? Auth.homePage() : "overview";
    return { page, query };
  },

  syncHash() {
    const next =
      this.page === "login"
        ? "login"
        : this.page + (this.query ? "?" + this.query : "");
    const cur = (location.hash || "").replace(/^#/, "");
    if (cur !== next) {
      try {
        history.replaceState(null, "", "#" + next);
      } catch (e) {
        location.hash = next;
      }
    }
  },

  navigate(page, queryObj) {
    let pageId = String(page || "overview").replace(/^#/, "").replace(/\.html$/, "");
    let query = "";

    if (pageId.includes("?")) {
      const parts = pageId.split("?");
      pageId = parts[0];
      query = parts.slice(1).join("?");
    }

    if (queryObj && typeof queryObj === "object") {
      query = new URLSearchParams(queryObj).toString();
    } else if (typeof queryObj === "string" && queryObj) {
      query = queryObj.replace(/^\?/, "");
    }

    if (pageId === "index" || pageId === "") pageId = Auth.homePage();
    if (pageId !== "login" && !PAGE_IDS.includes(pageId)) pageId = Auth.homePage();
    if (pageId !== "login" && !Auth.canAccess(pageId)) pageId = Auth.homePage();

    this.page = pageId;
    this.query = query;
    this.syncHash();
    render();
  },
};

function setNavActive(page) {
  document.querySelectorAll("[data-route]").forEach((btn) => {
    btn.classList.toggle("active", btn.getAttribute("data-route") === page);
  });
}

function applyRoleUI() {
  const admin = Auth.isAdmin();
  document.body.classList.toggle("role-admin", admin);
  document.body.classList.toggle("role-user", !admin);

  document.querySelectorAll("[data-admin-only]").forEach((el) => {
    el.hidden = !admin;
  });
  document.querySelectorAll("[data-user-only]").forEach((el) => {
    el.hidden = admin;
  });

  const user = Auth.username();
  const label = document.getElementById("user-label");
  const avatar = document.getElementById("user-avatar");
  const display = user.includes("@") ? user.split("@")[0] : user;
  if (label) label.textContent = display || "User";
  if (avatar) avatar.textContent = (display || "U").slice(0, 2).toUpperCase();
}

function closeCatalogDrawer() {
  const host = document.getElementById("catalog-drawer-root");
  if (host) host.remove();
}

function showLogin() {
  document.body.className = "login-body";
  document.body.dataset.page = "login";
  document.getElementById("view-login").hidden = false;
  document.getElementById("view-app").hidden = true;
  closeCatalogDrawer();
  const modal = document.getElementById("sn-modal-root");
  if (modal) modal.remove();
}

function showApp(page) {
  document.body.className = "";
  document.body.dataset.page = page;
  document.getElementById("view-login").hidden = true;
  document.getElementById("view-app").hidden = false;

  closeCatalogDrawer();
  applyRoleUI();
  if (window.BotRunner) BotRunner.updateTopbar();

  const titleEl = document.getElementById("page-title");
  if (titleEl) titleEl.textContent = PAGE_TITLES[page] || page;

  setNavActive(page);

  document.querySelectorAll("[data-page-panel]").forEach((panel) => {
    const isActive = panel.getAttribute("data-page-panel") === page;
    panel.hidden = !isActive;
    if (isActive) {
      const root = panel.querySelector("[id$='-root']");
      if (root) root.innerHTML = "";
    }
  });

  if (typeof window.Pages[page] === "function") {
    window.Pages[page]();
  }
}

function render() {
  const signedIn = Auth.isSignedIn();
  let page = window.AppRouter.page;

  if (!signedIn) {
    if (page !== "login") {
      window.AppRouter.page = "login";
      window.AppRouter.query = "";
      window.AppRouter.syncHash();
    }
    showLogin();
    return;
  }

  if (page === "login") {
    window.AppRouter.navigate(Auth.homePage());
    return;
  }

  if (!Auth.canAccess(page)) {
    window.AppRouter.navigate(Auth.homePage());
    return;
  }

  showApp(page);
}

function routeFromHref(href) {
  if (!href) return null;
  const raw = String(href).trim();

  if (/^(https?:|mailto:|tel:|javascript:)/i.test(raw)) return null;

  if (raw.startsWith("#")) {
    const body = raw.slice(1);
    const [p, q = ""] = body.split("?");
    return { page: p || "overview", query: q };
  }

  const cleaned = raw.replace(/^\.\//, "").replace(/^\//, "");
  const m = cleaned.match(
    /^(index|login|catalog|run|reports|evidence|exceptions|settings|users)\.html(?:\?(.*))?$/i
  );
  if (m) {
    let page = m[1].toLowerCase();
    if (page === "index") page = "overview";
    return { page, query: m[2] || "" };
  }

  return null;
}

function wireShellEvents() {
  const form = document.getElementById("login-form");
  if (form && !form.dataset.wired) {
    form.dataset.wired = "1";
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const userEl = document.getElementById("login-user");
      const username = userEl ? userEl.value : "";
      Auth.signIn(username);
      window.AppRouter.navigate(Auth.homePage());
    });
  }

  const toggle = document.getElementById("password-toggle");
  const pass = document.getElementById("login-pass");
  if (toggle && pass && !toggle.dataset.wired) {
    toggle.dataset.wired = "1";
    toggle.addEventListener("click", () => {
      const show = pass.type === "password";
      pass.type = show ? "text" : "password";
      toggle.classList.toggle("is-visible", show);
      toggle.setAttribute("aria-pressed", show ? "true" : "false");
      toggle.setAttribute("aria-label", show ? "Hide password" : "Show password");
    });
  }

  const logout = document.getElementById("logout-btn");
  if (logout && !logout.dataset.wired) {
    logout.dataset.wired = "1";
    logout.addEventListener("click", () => {
      Auth.signOut();
      window.AppRouter.navigate("login");
    });
  }

  const botStatus = document.getElementById("bot-run-status");
  if (botStatus && !botStatus.dataset.wired) {
    botStatus.dataset.wired = "1";
    botStatus.addEventListener("click", () => {
      if (window.BotRunner && BotRunner.job) BotRunner.expand();
    });
  }

  if (!document.documentElement.dataset.routeWired) {
    document.documentElement.dataset.routeWired = "1";

    document.addEventListener(
      "click",
      (e) => {
        const routeBtn = e.target.closest("[data-route]");
        if (routeBtn) {
          if (routeBtn.hidden) return;
          e.preventDefault();
          e.stopPropagation();
          window.AppRouter.navigate(routeBtn.getAttribute("data-route"));
          return;
        }

        const a = e.target.closest("a[href]");
        if (!a) return;
        const route = routeFromHref(a.getAttribute("href"));
        if (!route) return;
        e.preventDefault();
        e.stopPropagation();
        window.AppRouter.navigate(route.page, route.query);
      },
      true
    );
  }
}

appsmith.onReady(() => {
  wireShellEvents();

  const fromHash = window.AppRouter.parseHash();
  const signedIn = Auth.isSignedIn();

  if (fromHash) {
    window.AppRouter.page = fromHash.page;
    window.AppRouter.query = fromHash.query;
  } else {
    window.AppRouter.page = signedIn ? Auth.homePage() : "login";
    window.AppRouter.query = "";
    window.AppRouter.syncHash();
  }

  window.addEventListener("hashchange", () => {
    const h = window.AppRouter.parseHash();
    if (!h) return;
    if (h.page === window.AppRouter.page && h.query === window.AppRouter.query) return;
    window.AppRouter.page = h.page;
    window.AppRouter.query = h.query;
    render();
  });

  render();
});

