}



.prev-run {

  display: flex;

  flex-direction: column;

  gap: 10px;

  padding: 12px 14px;

  border: 1px solid var(--border);

  border-radius: 12px;

  background: var(--surface-2);

  text-decoration: none;

  color: inherit;

  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;

}



.prev-run:hover {

  border-color: #ffd2bf;

  background: #fffaf7;

  box-shadow: 0 4px 14px rgba(26, 29, 38, 0.06);

}



.prev-run-top {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  min-width: 0;

}



.prev-run-top strong {

  color: var(--text);

  font-size: 14px;

  font-weight: 700;

  white-space: nowrap;

}



.prev-run-top .badge {

  flex-shrink: 0;

}



.prev-run-file {

  display: block;

  color: var(--text-3);

  font-size: 12px;

  line-height: 1.35;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;

}



.prev-run-foot {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  min-width: 0;

}



.prev-run-stats {

  display: flex;

  flex-wrap: wrap;

  gap: 8px;

  min-width: 0;

}



.prev-run-stat {

  display: inline-flex;

  align-items: center;

  gap: 4px;

  padding: 3px 8px;

  border-radius: 999px;

  background: #fff;

  border: 1px solid var(--border);

  font-size: 11px;

  font-weight: 650;

  color: var(--text-3);

  white-space: nowrap;

}



.prev-run-stat em {

  font-style: normal;

  color: var(--text);

  font-variant-numeric: tabular-nums;

}



.prev-run-stat.ok em {

  color: var(--aa-orange-dark);

}



.prev-run-stat.bad em {

  color: var(--fail);

}



.prev-run-stat.run em {

  color: #9a6b0a;

}



.prev-run-time {

  color: var(--text-4);

  font-size: 11px;

  white-space: nowrap;

  flex-shrink: 0;

}



.pass-rate-inline {

  display: inline-flex;

  align-items: center;

  gap: 10px;

  min-width: 160px;

}



.pass-rate-inline .progress {

  width: 88px;

  flex-shrink: 0;

}



.pass-rate-inline strong {

  color: var(--text);

  font-size: 14px;

  font-variant-numeric: tabular-nums;

}



.pass-rate-inline .muted {

  font-size: 12px;

  font-weight: 600;

  text-transform: uppercase;

  letter-spacing: 0.03em;

}



.chip {

  display: inline-block;

  margin: 3px;

  padding: 6px 10px;

  border-radius: 8px;

  background: var(--aa-orange-soft);

  font-size: 12px;

  color: var(--aa-orange-dark);

  white-space: nowrap;

}



#catalog-drawer-root {

  position: fixed;

  inset: 0;

  z-index: 20000;

}



.drawer-bg {

  position: absolute;

  inset: 0;

  background: rgba(26, 29, 38, 0.18);

  z-index: 1;

  opacity: 0;

  transition: opacity 0.28s ease;

}



.drawer-bg.is-open {

  opacity: 1;

}



.drawer {

  position: absolute;

  top: 0;

  right: 0;

  bottom: 0;

  width: min(560px, 100%);

  background: var(--surface);

  border-left: 1px solid var(--border);

  z-index: 2;

  display: flex;

  flex-direction: column;

  box-shadow: -16px 0 48px rgba(26, 29, 38, 0.16);

  transform: translateX(100%);

  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);

}



.drawer.is-open {

  transform: translateX(0);

}



.drawer-hd,

.drawer-ft {

  padding: 20px;

  border-bottom: 1px solid var(--border);

}



.drawer-hd {

  position: relative;

  padding-left: 56px;

}



.drawer-close-x {

  position: absolute;

  top: 22px;

  left: 12px;

  z-index: 3;

  width: 36px;

  height: 36px;

  border-radius: 8px;

  border: 1px solid var(--border);

  background: #ffffff;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  color: var(--text);

}



.drawer-close-x svg {

  width: 18px;

  height: 18px;

}



.drawer-close-x:hover {

  background: var(--surface-2);

  color: var(--text);

}



.drawer-ft {

  border-bottom: 0;

  border-top: 1px solid var(--border);

  display: flex;

  justify-content: flex-end;

  gap: 10px;

  flex-wrap: wrap;

}





#page-catalog table tbody tr {

  cursor: pointer;

}

#page-catalog table tbody tr:hover {

  background: var(--aa-orange-soft);

}

.drawer-bd {

  flex: 1;

  overflow: auto;

  padding: 20px;

}



.folder-btn {

  width: 100%;

  display: flex;

  align-items: flex-start;

  gap: 10px;

  text-align: left;

  padding: 12px;

  border-radius: 10px;

  color: var(--text-3);

  font-size: 14px;

}



.folder-btn .folder-ico {

  width: 20px;

  height: 20px;

  flex-shrink: 0;

  margin-top: 1px;

  color: var(--aa-orange);

}



.folder-btn:hover,

.folder-btn.on {

  background: var(--aa-orange-soft);

  color: var(--aa-orange-dark);

}



.ev-folder-list {

  padding-top: 8px;

  display: flex;

  flex-direction: column;

  gap: 4px;

  max-height: 64vh;

  overflow: auto;

}



.folder-grid {

  display: grid;

  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));

  gap: 12px;

}



.case-folder {

  text-align: left;

  padding: 16px;

  border-radius: 12px;

  border: 1px solid var(--border);

  background: var(--surface-2);

  width: 100%;

}



.case-folder:hover,

.case-folder:focus-visible {

  border-color: #ffd2bf;

  background: var(--aa-orange-soft);

}



.case-folder-hd {

  display: flex;

  justify-content: space-between;

  align-items: center;

  gap: 8px;

  margin-bottom: 8px;

  flex-wrap: wrap;

}



.folder-glyph {

  display: block;

  width: 42px;

  height: 30px;

  margin-bottom: 12px;

  background: linear-gradient(180deg, #ff8a4c, var(--aa-orange));

  border-radius: 0 6px 6px 6px;

  position: relative;

  box-shadow: 0 6px 12px -8px rgba(226, 85, 43, 0.8);

}



.folder-glyph::before {

  content: "";

  position: absolute;

  top: -7px;

  left: 0;

  width: 18px;

  height: 10px;

  background: var(--aa-coral);

  border-radius: 4px 4px 0 0;

}



.crumb {

  display: flex;

  flex-wrap: wrap;

  align-items: center;

  gap: 6px;

  margin-top: 6px;

  font-size: 12px;

  color: var(--text-4);

  font-family: var(--mono);

}



.crumb button {

  color: var(--aa-orange-dark);

  font-weight: 650;

}



.crumb button:hover {

  text-decoration: underline;

}



.shot-grid {

  display: grid;

  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));

  gap: 12px;

}



.shot {

  width: 100%;

  text-align: left;

  border: 1px solid var(--border);

  border-radius: 12px;

  overflow: hidden;

  background: #fff;

}



.shot:hover,

.shot.on {

  border-color: #ffd2bf;

  box-shadow: 0 8px 18px -12px rgba(226, 85, 43, 0.7);

}



.shot-meta {

  padding: 10px 12px 12px;

  display: flex;

  flex-direction: column;

  gap: 6px;

}



.shot-meta strong {

  font-size: 12px;

  font-family: var(--mono);

  color: var(--text);

  word-break: break-all;

}



.shot-meta span {

  display: flex;

  align-items: center;

  gap: 8px;

  flex-wrap: wrap;

  font-size: 11px;

  color: var(--text-4);

}



.shot-frame {

  background: #f3f5f9;

  border-bottom: 1px solid var(--border);

}



.shot-chrome {

  display: flex;

  align-items: center;

  gap: 8px;

  height: 26px;

  padding: 0 10px;

  background: linear-gradient(90deg, #ff6a3d, #ff8a4c);

  color: #fff;

  font-size: 10px;

  font-weight: 650;

}



.shot-dots {

  width: 28px;

  height: 6px;

  border-radius: 99px;

  background: rgba(255, 255, 255, 0.55);

}



.shot-canvas {

  padding: 10px 12px 12px;

  min-height: 92px;

}



.shot-frame.lg .shot-canvas {

  min-height: 280px;

  padding: 20px 24px 24px;

}



.shot-frame.lg .shot-chrome {

  height: 36px;

  font-size: 13px;

}



.shot-title {

  font-size: 12px;

  font-weight: 650;

  color: var(--text);

  margin-bottom: 8px;

}



.shot-frame.lg .shot-title {

  font-size: 18px;

  margin-bottom: 14px;

}



.shot-rows {

  display: grid;

  gap: 6px;

}



.shot-rows i {

  display: block;

  height: 8px;

  border-radius: 4px;

  background: #e4e8f0;

}



.shot-rows i:nth-child(1) { width: 78%; }

.shot-rows i:nth-child(2) { width: 62%; }

.shot-rows i:nth-child(3) { width: 48%; }



.shot-frame.lg .shot-rows i {

  height: 14px;

}



.shot-alert {

  margin-top: 8px;

  padding: 6px 8px;

  border-radius: 6px;

  background: rgba(159, 18, 57, 0.1);

  color: #9f1239;

  font-size: 10px;

  line-height: 1.4;

}



.shot-frame.lg .shot-alert {

  margin-top: 16px;

  padding: 12px 14px;

  font-size: 14px;

}



.shot-live {

  margin-top: 8px;

  color: #9a6b0a;

  font-size: 11px;

  font-weight: 650;

}



.shot-frame.fail .shot-chrome {

  background: linear-gradient(90deg, #9f1239, #be185d);

}



.shot-lightbox {

  position: fixed;

  inset: 0;

  z-index: 80;

  background: rgba(18, 22, 32, 0.55);

  display: grid;

  place-items: center;

  padding: 24px;

}



.shot-lightbox-card {

  width: min(820px, 100%);

  background: #fff;

  border-radius: 16px;

  overflow: hidden;

  box-shadow: 0 24px 60px rgba(18, 22, 32, 0.28);

}



.card-btn {

  text-align: left;

  padding: 16px;

  border-radius: 12px;

  border: 1px solid var(--border);

  background: var(--surface-2);

  width: 100%;

}



.card-btn.on,

.card-btn:hover {

  border-color: #ffd2bf;

  background: var(--aa-orange-soft);

}



@media (max-width: 720px) {

  .content {

    padding: 10px 8px;

  }

  .page-hd h2 {

    font-size: 22px;

  }

  .stat .value {

    font-size: 26px;

  }

  .topbar {

    padding: 10px 10px;

  }

}



/* Login — plain white + modern card */

.login-body {

  min-height: 100%;

  height: 100%;

  margin: 0;

  background: #ffffff;

  color: var(--text);

}



.login-shell {

  min-height: 100%;

  height: 100%;

  display: grid;

  place-items: center;

  padding: 16px;

  box-sizing: border-box;

}



.login-card {

  width: 100%;

  max-width: 340px;

  background: #fff;

  border: 1px solid #e8ebf2;

  border-radius: 16px;

  padding: 0 28px 24px;

  overflow: hidden;

  box-shadow:

    0 1px 2px rgba(26, 29, 38, 0.04),

    0 18px 40px -20px rgba(26, 29, 38, 0.18);

  animation: loginRise 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;

}



.login-banner {

  height: 8px;

  margin: 0 -28px 28px;

  background: linear-gradient(90deg, #ff8a4c 0%, var(--aa-orange) 50%, var(--aa-orange-dark) 100%);

}



.login-brand {

  display: flex;

  align-items: center;

  gap: 10px;

  margin-bottom: 20px;

}



.login-brand strong {

  display: block;

  font-size: 11px;

  font-weight: 800;

  color: var(--text);

  line-height: 1.1;

}



.login-brand span {

  display: block;

  font-size: 14px;

  font-weight: 750;

  color: var(--aa-orange-dark);

  line-height: 1.1;

  margin-top: 0;

}



.login-card h1 {

  margin: 0;

  font-size: 22px;

  font-weight: 750;

  letter-spacing: -0.03em;

  color: var(--text);

}



.login-sub {

  margin: 8px 0 0;

  color: var(--text-3);

  font-size: 13px;

  line-height: 1.5;

}



.login-form {

  margin-top: 20px;

  display: flex;

  flex-direction: column;

  gap: 10px;

}



.login-form input {

  height: 42px;

  width: 100%;

  padding: 0 12px;

  border-radius: 10px;

  border: 1px solid var(--border-strong);

  background: #fafbfc;

  color: var(--text);

  font-size: 14px;

  font-weight: 550;

  outline: none;

  transition: 0.15s ease;

}



.login-form input::placeholder {

  color: var(--text-4);

  font-weight: 500;

}



.login-form input:focus {

  border-color: var(--aa-orange);

  background: #fff;

  box-shadow: 0 0 0 3px rgba(255, 106, 61, 0.12);

}



.login-btn {

  width: 100%;

  height: 42px;

  margin-top: 4px;

  border-radius: 12px;

}



.login-btn:hover {

  filter: brightness(1.04);

}



.login-foot {

  margin: 22px 0 0;

  text-align: center;

  font-size: 12px;

  color: var(--text-4);

  font-weight: 600;

}



@keyframes loginRise {

  from {

    opacity: 0;

    transform: translateY(10px);

  }

  to {

    opacity: 1;

    transform: none;

  }

}



/* Nav buttons (same look as original <a> nav links) */
.nav .nav-btn,
.mobile-nav .nav-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 12px 14px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--text-3);
  font: inherit;
  font-size: 15px;
  font-weight: 550;
  text-align: left;
  cursor: pointer;
  transition: 0.15s ease;
  position: relative;
  white-space: nowrap;
}
.nav .nav-btn:hover,
.mobile-nav .nav-btn:hover {
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
}
.nav .nav-btn.active,
.mobile-nav .nav-btn.active {
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
  font-weight: 650;
}
.nav .nav-btn.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 20px;
  border-radius: 0 4px 4px 0;
  background: var(--aa-orange);
}
.nav .nav-btn:hover .nav-icon,
.nav .nav-btn.active .nav-icon,
.mobile-nav .nav-btn:hover .nav-icon,
.mobile-nav .nav-btn.active .nav-icon {
  opacity: 1;
}

.mobile-nav .nav-btn {
  width: auto;
  flex: 0 0 auto;
}

/* Restore spacing: page roots are .stack; keep gap even if flex gap is odd in iframe */
.stack > * + * {
  margin-top: 0; /* gap handles spacing when supported */
}
@supports not (gap: 20px) {
  .stack > * + * {
    margin-top: 20px;
  }
}

/* Appsmith Custom Widget viewport — fill iframe only; never grow past it */
html, body {
  height: 100% !important;
  min-height: 100% !important;
  max-height: 100% !important;
  width: 100%;
  max-width: 100%;
  overflow: hidden !important;
  margin: 0;
}
#root {
  height: 100% !important;
  min-height: 100% !important;
  max-height: 100% !important;
  width: 100%;
  max-width: 100%;
  overflow: hidden !important;
  background: var(--bg);
  box-sizing: border-box;
}
#root .app {
  min-height: 100% !important;
  height: 100% !important;
  max-height: 100% !important;
  width: 100%;
  max-width: 100%;
  overflow: hidden !important;
}
/* Always show desktop sidebar inside the widget (iframe width can be < 960) */
#root .sidebar {
  display: flex !important;
  height: 100% !important;
  position: relative;
  top: auto;
  flex-shrink: 0;
}
#root .mobile-nav {
  display: none !important;
}
#root .main-wrap {
  height: 100%;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
#root .content {
  flex: 1;
  overflow: auto;
  min-height: 0;
  min-width: 0;
  max-width: 100%;
  width: 100%;
  padding: 12px 10px !important;
  margin: 0 !important;
  box-sizing: border-box;
}
#root .topbar {
  padding-left: 12px !important;
  padding-right: 12px !important;
}
#root .app,
#root .main-wrap,
#root #view-app:not([hidden]) {
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 !important;
}
#root .page-panel,
#root .stack,
#root .grid-2,
#root .overview-split,
#root .overview-side,
#root .panel {
  min-width: 0;
  max-width: 100%;
}
#root .scroll {
  max-width: 100%;
  overflow-x: auto;
}
#root .filters {
  grid-template-columns: minmax(0, 1.5fr) repeat(3, minmax(0, 1fr));
}
@media (max-width: 900px) {
  #root .filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
#root .catalog-actions {
  flex-wrap: wrap;
  max-width: 100%;
}
#root .login-body,
#root .login-shell {
  min-height: 100% !important;
  height: 100% !important;
  max-height: 100% !important;
  overflow: auto;
  box-sizing: border-box;
}
#root #view-login:not([hidden]),
#root #view-app:not([hidden]) {
  height: 100% !important;
  min-height: 100% !important;
  max-height: 100% !important;
}
#root .page-panel[hidden],
#root #view-login[hidden],
#root #view-app[hidden] {
  display: none !important;
}
#root .page-panel:not([hidden]) {
  display: block;
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
}




