  height: 13px;
}

.sn-chip.pass {
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
  border-color: #ffd2bf;
}
.sn-chip.fail {
  background: rgba(159, 18, 57, 0.1);
  color: #9f1239;
  border-color: rgba(159, 18, 57, 0.28);
}
.sn-chip.warn {
  background: #fff8e8;
  color: var(--warn);
  border-color: #f3dfae;
}
.sn-chip.info {
  background: var(--info-soft);
  color: #9a6b0a;
  border-color: #f5d48a;
}
.sn-chip.violet {
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
  border-color: #ffd2bf;
}
.sn-chip.neutral {
  background: #f1f3f8;
  color: var(--text-3);
  border-color: var(--border);
}

.sn-view-more {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 34px;
  padding: 0 12px;
  font-size: 13px;
  gap: 6px;
}

.sn-table td {
  vertical-align: middle;
}

.sn-card-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: minmax(0, 1fr);
}

@media (min-width: 720px) {
  .sn-card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1100px) {
  .sn-card-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.sn-card {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 100%;
  border-radius: 12px;
  background: linear-gradient(180deg, #ffffff 0%, #fafbfc 100%);
}

.sn-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.sn-card .sn-mono {
  font-size: 11px;
  letter-spacing: 0.02em;
}

.sn-card .sn-time {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-4);
}

.sn-card-title {
  margin: 0;
  font-size: 13px;
  font-weight: 650;
  color: var(--text);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.sn-card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.sn-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: auto;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}

.sn-assignee {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--text-4);
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 55%;
}

.sn-chip-sm {
  height: 22px;
  padding: 0 8px;
  font-size: 10px;
  gap: 0;
}

.sn-view-more-sm {
  height: 28px;
  padding: 0 10px;
  font-size: 12px;
  border-radius: 8px;
}

#sn-modal-root {
  position: fixed;
  inset: 0;
  z-index: 10000;
  pointer-events: none;
}

#sn-modal-root .sn-modal-bg,
#sn-modal-root .sn-modal {
  pointer-events: auto;
}

.sn-modal-bg {
  position: fixed;
  inset: 0;
  background: rgba(26, 29, 38, 0.55);
  z-index: 10000;
}

.sn-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 10001;
  width: min(640px, calc(100vw - 32px));
  max-height: min(82vh, 760px);
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: 0 28px 60px rgba(26, 29, 38, 0.28);
}

.sn-modal-hd {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 20px 14px;
  border-bottom: 1px solid var(--border);
}

.sn-modal-hd h3 {
  margin: 8px 0 8px;
  font-size: 17px;
  font-weight: 700;
  color: var(--text);
  line-height: 1.35;
}

.sn-modal-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.sn-modal-sub {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 16px;
  font-size: 13px;
  color: var(--text-3);
  font-weight: 600;
}

.sn-modal-sub > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sn-modal-close {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  color: var(--text-3);
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.sn-modal-close:hover {
  background: var(--surface-2);
  color: var(--text);
}

.sn-modal-bd {
  padding: 16px 20px;
  overflow: auto;
  flex: 1;
}

.sn-steps {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sn-steps li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text-2);
  font-size: 14px;
  line-height: 1.45;
}

.sn-step-num {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  border: 1px solid var(--border);
  color: var(--text-3);
  font-size: 12px;
  font-weight: 750;
  flex-shrink: 0;
}

.sn-modal-msg {
  margin-top: 14px;
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
  font-size: 13px;
  font-weight: 650;
  display: flex;
  align-items: center;
  gap: 8px;
}

.sn-modal-ft {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  padding: 14px 20px;
  border-top: 1px solid var(--border);
}

.sn-modal-ft-right {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
}

.sn-run-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.sn-modal-ft .btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
}


.sn-instance-row {
  flex-direction: row;
  align-items: center;
  gap: 8px;
}

.sn-instance-row .sn-instance-label {
  display: inline;
  font-size: 12px;
  text-transform: none;
  letter-spacing: 0;
  color: var(--text-3);
  font-weight: 650;
  white-space: nowrap;
}

.sn-instance-row .sn-instance-label::after {
  content: "";
}

.sn-instance-row strong {
  max-width: min(360px, 55vw);
  font-size: 13px;
}

.sn-card-actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.sn-del-btn {
  color: #9f1239;
  border-color: rgba(159, 18, 57, 0.28);
}

.sn-del-btn:hover {
  background: rgba(159, 18, 57, 0.08);
  color: #9f1239;
  border-color: rgba(159, 18, 57, 0.4);
}

.res-dl-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 34px;
  padding: 0 12px;
  font-size: 13px;
}

.res-dl-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
}

.res-dl-btn .sn-ico svg {
  width: 15px;
  height: 15px;
}

.bot-run-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid #f5d48a;
  background: var(--info-soft);
  color: #9a6b0a;
  font-size: 13px;
  font-weight: 650;
  white-space: nowrap;
  cursor: pointer;
}

.bot-run-status.is-running {
  border-color: #f5d48a;
  background: var(--info-soft);
  color: #9a6b0a;
}

.bot-run-status.is-done {
  border-color: #ffd2bf;
  background: var(--aa-orange-soft);
  color: var(--aa-orange-dark);
}

.bot-run-status.is-fail {
  border-color: rgba(159, 18, 57, 0.28);
  background: rgba(159, 18, 57, 0.1);
  color: #9f1239;
}

.bot-run-status[hidden] {
  display: none !important;
}

.bot-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #f5a623;
  box-shadow: 0 0 0 0 rgba(245, 166, 35, 0.55);
  animation: bot-pulse 1.2s ease infinite;
}

.bot-pulse.done {
  background: var(--aa-orange);
  animation: none;
}

.bot-pulse.fail {
  background: #9f1239;
  animation: none;
}

@keyframes bot-pulse {
  0% { box-shadow: 0 0 0 0 rgba(245, 166, 35, 0.5); }
  70% { box-shadow: 0 0 0 8px rgba(245, 166, 35, 0); }
  100% { box-shadow: 0 0 0 0 rgba(245, 166, 35, 0); }
}

.bot-run-hint {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--text-3);
  line-height: 1.45;
  max-width: 460px;
}

.bot-run-progress {
  height: 8px;
  border-radius: 999px;
  background: #eef0f6;
  overflow: hidden;
  margin-bottom: 14px;
}

.bot-run-progress > span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--aa-orange), var(--aa-coral));
  transition: width 0.35s ease;
}

.bot-run-steps li {
  align-items: center;
}

.bot-run-steps li.is-running {
  border-color: #f5d48a;
  background: #fffaf0;
}

.bot-run-step-name {
  flex: 1;
  min-width: 0;
}

#bot-run-modal-root {
  position: fixed;
  inset: 0;
  z-index: 10020;
  pointer-events: none;
}

#bot-run-modal-root .sn-modal-bg,
#bot-run-modal-root .sn-modal {
  pointer-events: auto;
}

#btn-run:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
}

.bot-run-simple {
  width: min(420px, calc(100vw - 32px));
  max-height: none;
  padding: 28px 24px 22px;
  position: relative;
}

.bot-run-simple .bot-run-x {
  position: absolute;
  top: 12px;
  right: 12px;
}

.bot-run-simple-body {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
}

.bot-run-simple-body h3 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: var(--text);
}

.bot-run-simple .bot-run-hint {
  margin: 0;
  max-width: 320px;
}

.bot-run-simple-actions {
  display: flex;
  gap: 10px;
  margin-top: 8px;
}

.bot-run-anim {
  width: 72px;
  height: 40px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 0;
}

.bot-run-anim.is-ok {
  background: transparent;
  border: 0;
  color: var(--aa-orange-dark);
}

.bot-run-anim.is-fail {
  background: transparent;
  border: 0;
  color: #9f1239;
}

.bot-dots {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.bot-dots i {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #f5a623;
  display: block;
  animation: bot-dot 1.2s ease-in-out infinite;
}

.bot-dots i:nth-child(2) {
  animation-delay: 0.2s;
}

.bot-dots i:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes bot-dot {
  0%, 80%, 100% {
    opacity: 0.3;
    transform: translateY(0) scale(0.85);
  }
  40% {
    opacity: 1;
    transform: translateY(-4px) scale(1);
  }
}

.bot-run-check {
  font-size: 26px;
  font-weight: 700;
  line-height: 1;
}

