window.Utils = {
  fmtDuration(sec) {
    if (!sec && sec !== 0) return "—";
    const m = Math.floor(sec / 60);
    const s = Math.round(sec % 60);
    return m ? `${m}m ${String(s).padStart(2, "0")}s` : `${s}s`;
  },

  fmtTime(iso) {
    if (!iso) return "—";
    return new Date(iso).toLocaleString("en-GB", {
      day: "2-digit",
      month: "short",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });
  },

  money(v, ccy) {
    return `${ccy} ${Number(v).toLocaleString("en-US")}`;
  },

  resultTone(result) {
    if (result === "Pass" || result === "Passed") return "pass";
    if (result === "Fail" || result === "Failed") return "fail";
    if (result === "Blocked") return "warn";
    if (result === "Running" || result === "InProgress") return "info";
    return "neutral";
  },

  qs(name) {
    if (window.AppRouter && typeof window.AppRouter.getQuery === "function") {
      const fromRouter = window.AppRouter.getQuery(name);
      if (fromRouter != null && fromRouter !== "") return fromRouter;
    }
    const fromSearch = new URLSearchParams(location.search || "").get(name);
    if (fromSearch != null && fromSearch !== "") return fromSearch;
    const hash = (location.hash || "").replace(/^#/, "");
    const q = hash.includes("?") ? hash.split("?")[1] : "";
    return new URLSearchParams(q).get(name);
  },

  progress(value, tone) {
    const pct = Math.max(0, Math.min(100, Math.round(value * 100)));
    return `<div class="progress ${tone || ""}"><span style="width:${pct}%"></span></div>`;
  },

  badge(text, tone) {
    return `<span class="badge ${tone || "neutral"}">${text}</span>`;
  },
};


/* =========================================================
   BOT RUNNER — shared run modal + topbar status
   ========================================================= */
window.BotRunner = {
  job: null,
  timer: null,
  minimized: false,

  isActive() {
    return !!(this.job && (this.job.status === "running" || this.job.status === "done"));
  },

  start(opts) {
    const steps = (opts.steps || []).filter(Boolean);
    if (!steps.length) return;

    this.stopTimer();
    this.job = {
      id: "run-" + Date.now(),
      title: opts.title || "Bot run",
      source: opts.source || "catalog",
      storyId: opts.storyId || null,
      steps: steps.map((name) => ({ name, status: "Pending" })),
      index: 0,
      progress: 0,
      status: "running",
      result: null,
      onComplete: typeof opts.onComplete === "function" ? opts.onComplete : null,
      startedAt: Date.now(),
    };
    this.minimized = false;
    this.renderModal();
    this.updateTopbar();
    this.timer = setInterval(() => this.tick(), 700);
  },

  tick() {
    const job = this.job;
    if (!job || job.status !== "running") return;

    const step = job.steps[job.index];
    if (!step) {
      this.finish(Math.random() < 0.88 ? "Passed" : "Failed");
      return;
    }

    if (step.status === "Pending") {
      step.status = "Running";
    } else if (step.status === "Running") {
      step.status = "Passed";
      job.index += 1;
    }

    job.progress = Math.min(1, (job.index + (step.status === "Running" ? 0.45 : 0)) / job.steps.length);

    if (job.index >= job.steps.length) {
      this.finish(Math.random() < 0.88 ? "Passed" : "Failed");
      return;
    }

    if (!this.minimized) {
      // Keep simple modal stable while running; refresh only when needed
      const title = document.getElementById("bot-run-title");
      if (!title || title.textContent !== "Bot Running") this.renderModal();
    }
    this.updateTopbar();
  },

  finish(result) {
    this.stopTimer();
    if (!this.job) return;
    this.job.status = "done";
    this.job.result = result;
    this.job.progress = 1;
    this.job.steps.forEach((s) => {
      if (s.status !== "Passed") s.status = "Passed";
    });
    if (this.job.onComplete) {
      try {
        this.job.onComplete(result);
      } catch (e) {}
    }
    if (!this.minimized) this.renderModal();
    this.updateTopbar();
  },

  stopTimer() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  },

  minimize() {
    this.minimized = true;
    this.removeModal();
    this.updateTopbar();
  },

  closeUi() {
    // Close/dismiss UI; keep job running or finished in background
    this.minimize();
  },

  expand() {
    if (!this.job) return;
    this.minimized = false;
    this.renderModal();
    this.updateTopbar();
  },

  dismiss() {
    // Fully clear after done, or minimize if still running
    if (this.job && this.job.status === "running") {
      this.minimize();
      return;
    }
    this.stopTimer();
    this.job = null;
    this.minimized = false;
    this.removeModal();
    this.updateTopbar();
  },

  removeModal() {
    const el = document.getElementById("bot-run-modal-root");
    if (el) el.remove();
  },

  stepTone(status) {
    if (status === "Passed") return "pass";
    if (status === "Running") return "info";
    if (status === "Failed") return "fail";
    return "neutral";
  },

  renderModal() {
    const job = this.job;
    if (!job) return;
    const host = document.getElementById("root") || document.body;
    let root = document.getElementById("bot-run-modal-root");
    if (!root) {
      root = document.createElement("div");
      root.id = "bot-run-modal-root";
      host.appendChild(root);
    }

    const running = job.status === "running";

    root.innerHTML = `
      <div class="sn-modal-bg" id="bot-run-bg"></div>
      <div class="sn-modal bot-run-modal bot-run-simple" role="dialog" aria-modal="true" aria-labelledby="bot-run-title">
        <button type="button" class="sn-modal-close bot-run-x" id="bot-run-x" aria-label="Close">×</button>
        <div class="bot-run-simple-body">
          <div class="bot-run-anim ${running ? "is-spin" : job.result === "Passed" ? "is-ok" : "is-fail"}" aria-hidden="true">
            ${
              running
                ? `<span class="bot-dots"><i></i><i></i><i></i></span>`
                : job.result === "Passed"
                  ? `<span class="bot-run-check">✓</span>`
                  : `<span class="bot-run-check">!</span>`
            }
          </div>
          <h3 id="bot-run-title">${running ? "Bot Running" : job.result === "Passed" ? "Bot finished" : "Bot failed"}</h3>
          <p class="bot-run-hint">You can minimize or close this status message. The bot will keep running in the background.</p>
          <div class="bot-run-simple-actions">
            <button type="button" class="btn btn-outline" id="bot-run-min">Minimize</button>
            <button type="button" class="btn btn-outline" id="bot-run-close">${running ? "Close" : "Done"}</button>
          </div>
        </div>
      </div>`;

    document.getElementById("bot-run-min").onclick = () => this.minimize();
    document.getElementById("bot-run-close").onclick = () => this.dismiss();
    document.getElementById("bot-run-x").onclick = () => this.dismiss();
    document.getElementById("bot-run-bg").onclick = () => this.minimize();
  },

  updateTopbar() {
    const el = document.getElementById("bot-run-status");
    if (!el) return;
    const job = this.job;
    if (!job) {
      el.hidden = true;
      el.textContent = "";
      el.classList.remove("is-running", "is-done", "is-fail");
      return;
    }

    el.hidden = false;
    el.classList.toggle("is-running", job.status === "running");
    el.classList.toggle("is-done", job.status === "done" && job.result === "Passed");
    el.classList.toggle("is-fail", job.status === "done" && job.result !== "Passed");

    if (job.status === "running") {
      el.innerHTML = `<span class="bot-pulse"></span> Bot Running`;
    } else if (job.result === "Passed") {
      el.innerHTML = `<span class="bot-pulse done"></span> Bot finished · Passed`;
    } else {
      el.innerHTML = `<span class="bot-pulse fail"></span> Bot finished · Failed`;
    }
  },
};

