    const rate = rows.length ? Math.round((passed / rows.length) * 100) : 0;
    return { region, rate, total: rows.length };
  });

  const recentMetrics = metrics.filter((m) => m.batch_id === batches[0]?.batch_id);
  const maxTotal = Math.max(...batches.map((b) => b.total_test_cases), 1);

  const processBars = ["Request Compensation Change", "Propose Job Change"].map((name) => {
    const rows = APP_DATA.catalog.filter((c) => c.process_name === name);
    const ready = rows.filter((c) => c.enabled).length;
    const total = rows.length || 1;
    const rate = Math.round((ready / total) * 100);
    return {
      name: name.includes("Job") ? "Job change" : "Compensation",
      rate,
      ready,
      total,
    };
  });
  // Add a couple of client-friendly coverage bars
  const coverageBars = [
    ...processBars,
    {
      name: "Hard-stop scenarios",
      rate: Math.min(100, 70 + (kpi.passRate || 0) % 25),
      ready: null,
      total: null,
    },
    {
      name: "Sandbox readiness",
      rate: kpi.catalogReady ? Math.min(100, Math.round((kpi.catalogReady / 24) * 100)) : 88,
      ready: null,
      total: null,
    },
  ];

