      <div class="page-hd" style="align-items:flex-start">
        <div class="hero-copy">
          <h2>Workday Functional Test Agent</h2>
          <p>Monitor hard-stop validation across regions, review run health, and launch the next execution from Control Room.</p>
          <div class="hero-actions">
            <a class="btn btn-primary" href="#run">Start test run</a>
            <a class="btn btn-ghost" href="#reports">View results</a>
          </div>
        </div>
      </div>
    </div>

    <div class="stat-grid">
      <div class="stat-card tone-indigo">
        <p class="label">Passed</p>
        <p class="value">${kpi.passed ?? 0}</p>
        <p class="hint">Across completed cases</p>
      </div>
      <div class="stat-card tone-orange">
        <p class="label">Test runs</p>
        <p class="value">${kpi.batches}</p>
        <p class="hint">${kpi.catalogReady} active scenarios</p>
      </div>
      <div class="stat-card tone-rose">
        <p class="label">Failures</p>
        <p class="value">${kpi.failed}</p>
        <p class="hint">Needs review</p>
      </div>
      <div class="stat-card tone-sky">
        <p class="label">In progress</p>
        <p class="value">${kpi.inProgress}</p>
        <p class="hint">Currently running</p>
      </div>
    </div>

    <div class="grid-2 xl-2-1">
      <div class="panel">
        <div class="panel-hd">
          <h2>Recent run trend</h2>
          <div class="legend">
            <span><i style="background:#ff6a3d"></i>Passed</span>
            <span><i style="background:#9f1239"></i>Failed</span>
            <span><i style="background:#f5a623"></i>In progress</span>
          </div>
        </div>
        <div class="panel-bd">
          <div class="bar-chart">
            ${batches
              .slice(0, 8)
              .reverse()
              .map((b) => {
                const h = (n) => Math.max(4, Math.round((n / maxTotal) * 160));
                return `<div class="bar-col" title="Run ${b.batch_id}">
                  <div class="bar-stack" style="height:${h(b.total_test_cases)}px">
                    <div class="bar-seg bar-seg-pass" style="height:${h(b.passed_count)}px"></div>
                    <div class="bar-seg bar-seg-fail" style="height:${h(b.failed_count)}px"></div>
                    <div class="bar-seg bar-seg-wait" style="height:${h(b.in_progress_count)}px"></div>
                  </div>
                  <div class="bar-label">${String(b.batch_id)}</div>
                </div>`;
              })
              .join("")}
          </div>
        </div>
      </div>
      <div class="panel">
        <div class="panel-hd"><h2>Latest run summary</h2></div>
        <div class="panel-bd">
          ${
            recentMetrics.length
              ? recentMetrics
                  .map(
                    (m) => `<div class="region-row">
                    <div class="region-meta"><span>${m.process_name}</span><strong style="color:var(--aa-orange)">${m.total_count ? Math.round((m.passed_count / m.total_count) * 100) : 0}%</strong></div>
                    ${progress(m.total_count ? m.passed_count / m.total_count : 0, m.failed_count ? "amber" : "green")}
                    <div class="muted" style="font-size:12px;margin-top:4px">${m.scenario_name}</div>
                  </div>`,
                  )
