                <th class="right">Passed</th>
                <th class="right">Failed</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              ${batches
                .slice(0, 6)
                .map((b) => {
                  const tone =
                    b.overall_status === "Running"
