  function syncStepsModal(story) {
    let host = document.getElementById("story-steps-modal-root");
    if (!stepsModalOpen) {
      if (host) host.remove();
      return;
    }
    if (!host) {
      host = document.createElement("div");
      host.id = "story-steps-modal-root";
      document.body.appendChild(host);
    }
    host.innerHTML = stepsModalHtml();
    const close = () => {
      stepsModalOpen = false;
      host.remove();
      render();
    };
    const sx = host.querySelector("#story-steps-x");
    const sbg = host.querySelector("#story-steps-bg");
    if (sx) sx.onclick = close;
    if (sbg) sbg.onclick = close;
    const regen = host.querySelector("#story-regen-steps");
    if (regen) {
      regen.onclick = (e) => {
        e.stopPropagation();
        generatedSteps = buildGeneratedSteps(story || openStory());
        stepsGenerated = true;
        pushChat("user", "Regenerate steps");
        pushChat("assistant", "Steps were regenerated. Review them here, then continue with Generate Test Cases if needed.");
        syncStepsModal(story || openStory());
        const log = document.getElementById("story-chat-log");
        if (log) log.scrollTop = log.scrollHeight;
      };
    }
  }

