  function bindStoryChat() {
    const send = (text) => {
      const t = String(text || "").trim();
      if (!t) return;
      pushChat("user", t);
      pushChat("assistant", replyFor(t));
      render();
      const log = document.getElementById("story-chat-log");
      if (log) log.scrollTop = log.scrollHeight;
    };
    root.querySelectorAll("[data-hint]").forEach((btn) => {
      btn.onclick = () => send(btn.getAttribute("data-hint"));
    });
    const form = document.getElementById("story-chat-form");
    const input = document.getElementById("story-chat-input");
    if (form) {
      form.onsubmit = (e) => {
        e.preventDefault();
        const el = document.getElementById("story-chat-input");
        const val = el && el.value;
        send(val);
      };
    }
    if (input) {
      input.onkeydown = (e) => {
        if (e.key === "Enter" && !e.shiftKey) {
          e.preventDefault();
          form && form.requestSubmit ? form.requestSubmit() : form && form.dispatchEvent(new Event("submit", { cancelable: true }));
        }
      };
    }
  }

  function bindStoryDetail(story) {
    const back = document.getElementById("story-back");
    if (back) {
      back.onclick = () => {
        openId = null;
        message = "";
        chatMessages = [];
        openCase = null;
        const host = document.getElementById("story-case-drawer-root");
        if (host) host.remove();
        resetStoryGen();
        render();
      };
    }
    bindStoryChat();

    const gen = document.getElementById("story-generate");
    if (gen) {
      gen.onclick = () => {
        if (!stepsGenerated) {
          generatedSteps = buildGeneratedSteps(story);
          stepsGenerated = true;
          pushChat("user", "Generate Steps");
          pushChat("assistant", "Steps are ready. Click Steps to review them, or Generate Test Cases to build the catalog for this story.");
        } else {
          generatedCases = buildGeneratedCases(story);
          casesGenerated = true;
          APP_DATA.catalog = (APP_DATA.catalog || []).filter((c) => !c._fromStoryGen || String(c.story_id) !== String(story.sys_id));
          generatedCases.forEach((c) => {
            c._fromStoryGen = 1;
            APP_DATA.catalog.push(c);
          });
          pushChat("user", "Generate Test Cases");
          pushChat("assistant", "Test cases are ready in the Test cases panel on the left. Use Show in Test Catalog to open and select them.");
        }
        render();
        const log = document.getElementById("story-chat-log");
        if (log) log.scrollTop = log.scrollHeight;
      };
    }

    const stepsBtn = document.getElementById("story-steps-btn");
    if (stepsBtn) {
      stepsBtn.onclick = () => {
        if (!stepsGenerated) return;
        stepsModalOpen = true;
        syncStepsModal(story);
      };
    }

    syncStepsModal(story);

    const runBtn = document.getElementById("story-run-bot");
    if (runBtn) {
      runBtn.onclick = () => {
        if (!casesGenerated) return;
        runBot(story);
      };
    }
    const showCat = document.getElementById("story-show-catalog");
    if (showCat) {
      showCat.onclick = () => {
        if (!casesGenerated) return;
        sessionStorage.setItem("wfta_catalog_story", story.sys_id);
        sessionStorage.setItem("wfta_catalog_select_story", "1");
        if (typeof showApp === "function") showApp("catalog");
      };
    }

    root.querySelectorAll(".story-case-row").forEach((tr) => {
      tr.onclick = () => {
        const id = tr.getAttribute("data-case-id");
        openCase =
          generatedCases.find((c) => String(c.id) === String(id) || String(c.staging_id) === String(id)) ||
          null;
        syncCaseDrawer();
      };
    });

    syncCaseDrawer();
  }

